with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina taxa màxima d''alcohol en aire espirat poden tenir els conductors de vehicles destinats al transport escolar?', 'Rèplica de la pregunta 3 de Terrassa 2025. L''article 20 del Reglament general de circulació fixa per a aquests conductors 0,3 g/l en sang o 0,15 mg/l en aire espirat; la taxa general és 0,25 mg/l.', 'plcatexamen_2025_terrassa', (select id from public.topics where slug = 'plcatexamen-2025-terrassa'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514'), 'Art. 20 RGC', 'al transporte escolar y de menores, al de mercancías peligrosas o de servicio de urgencia o transportes especiales, los conductores no podrán hacerlo con una tasa de alcohol en sangre superior a 0,3 gramos por litro, o de alcohol en aire espirado superior a 0,15 miligramos por litro.', null, '09f4313f62dfeed1db3669c913996e5916ca6949561f1c1718d9a9b9ac031b8f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '09f4313f62dfeed1db3669c913996e5916ca6949561f1c1718d9a9b9ac031b8f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '0,25 mil·ligrams per litre.', false), ('B', '0,30 mil·ligrams per litre.', false), ('C', '0,15 mil·ligrams per litre.', true), ('D', '0,50 mil·ligrams per litre.', false)) as v(label, body, ok)
)
