  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan ho ordeni l''alcalde.', false), ('B', 'En cas de delicte flagrant.', true), ('C', 'Quan hi hagi sospites d''una infracció administrativa greu.', false), ('D', 'Durant les hores diürnes.', false)) as v(label, body, ok)
)
