with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 53.2 de la Constitució, el recurs d''empara davant el Tribunal Constitucional protegeix:', 'Rèplica de la pregunta 16 de Terrassa 2026. Article 53.2 CE.', 'plcatexamen_2026_terrassa', (select id from public.topics where slug = 'plcatexamen-2026-terrassa'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 53.2 CE', 'Cualquier ciudadano podrá recabar la tutela de las libertades y derechos reconocidos en el artículo 14 y la Sección primera del Capítulo segundo ante los Tribunales ordinarios', null, '78544b6fdee355e7b66f1b528c720240378424197bdde9c4886bdb863d6a4c76', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '78544b6fdee355e7b66f1b528c720240378424197bdde9c4886bdb863d6a4c76')
  returning id
), o as (
