insert into public.sources (title, url, kind, publisher, published_on) values ('Acord GOV/25/2015, de 24 de febrer, pel qual s''aprova el Codi d''ètica de la Policia de Catalunya (DOGC núm. 6821, 26/02/2015)', 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656', 'diario_autonomico'::public.source_kind, 'Generalitat de Catalunya · Portal Jurídic de Catalunya', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcatexamen-2026-terrassa', 'Examen rèplica · Terrassa 2026 (1f/AGENTS/2026), exercici teòric: 50 preguntes') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcatexamen-2026-terrassa' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi d''ètica de la Policia de Catalunya, quan es pot fer ús de la força?', 'Rèplica de la pregunta 9 de Terrassa 2026. El Codi configura la força com a últim recurs i la sotmet als principis d''oportunitat, congruència i proporcionalitat.', 'plcatexamen_2026_terrassa', (select id from public.topics where slug = 'plcatexamen-2026-terrassa'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656'), 'Codi d''ètica, ús de la força', 'En aquelles situacions en les quals es consideri que s’han exhaurit els mecanismes de resolució esmentats en el punt anterior o no hagi estat possible portar-los a terme, es podrà fer ús de la força quan sigui estrictament necessari per al compliment de les seves funcions.', null, 'ececb3a0d9c974ed4b0236ec548171bc83debdbcb07247880f04c30886a1b8db', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ececb3a0d9c974ed4b0236ec548171bc83debdbcb07247880f04c30886a1b8db')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan s''han exhaurit els mecanismes de resolució com la mediació i el diàleg, o no ha estat possible fer-los servir, i sigui estrictament necessari.', true), ('B', 'Sempre que l''agent ho consideri útil per agilitar la intervenció.', false), ('C', 'Només amb autorització prèvia del cap de torn.', false), ('D', 'Mai: la policia no pot fer ús de la força.', false)) as v(label, body, ok)
)
