with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 325.1 del Codi penal, quines d''aquestes conductes, fetes contravenint les normes protectores del medi ambient, poden constituir delicte contra el medi ambient?', 'Rèplica de la pregunta 1 de Terrassa 2026. L''article 325.1 CP inclou emissions, abocaments, radiacions, extraccions, excavacions, sorolls, vibracions, injeccions o dipòsits.', 'plcatexamen_2026_terrassa', (select id from public.topics where slug = 'plcatexamen-2026-terrassa'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 325.1 Codi penal', 'provoque o realice directa o indirectamente emisiones, vertidos, radiaciones, extracciones o excavaciones, aterramientos, ruidos, vibraciones, inyecciones o depósitos', null, 'dead18d3f75d735d75c3b60b3f9f8dc921bc999202565818d62354ff7fed789d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'dead18d3f75d735d75c3b60b3f9f8dc921bc999202565818d62354ff7fed789d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Provocar sorolls o vibracions.', false), ('B', 'Totes les altres opcions són correctes.', true), ('C', 'Fer extraccions o excavacions.', false), ('D', 'Provocar emissions o abocaments a l''atmosfera, el sòl o les aigües.', false)) as v(label, body, ok)
)
