with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina pena de presó preveu l''article 510.1 del Codi penal per a qui fomenta o incita públicament a l''odi o la violència contra un grup per motius racistes?', 'Rèplica de la pregunta 3 de Terrassa 2026. L''article 510.1 CP castiga aquestes conductes amb presó d''un a quatre anys; l''apartat 2 preveu de sis mesos a dos anys per a altres conductes.', 'plcatexamen_2026_terrassa', (select id from public.topics where slug = 'plcatexamen-2026-terrassa'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 510.1 Codi penal', 'Serán castigados con una pena de prisión de uno a cuatro años y multa de seis a doce meses', null, 'ac84a99c61d3a3a90c258824feda2e91662d86b0e19788ad7224f92adc753261', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ac84a99c61d3a3a90c258824feda2e91662d86b0e19788ad7224f92adc753261')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De sis mesos a dos anys, i multa de sis a dotze mesos.', false), ('B', 'De dos a cinc anys.', false), ('C', 'D''un a quatre anys, i multa de sis a dotze mesos.', true), ('D', 'De tres mesos a un any.', false)) as v(label, body, ok)
)
