  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relació amb els delictes de lesions del Codi penal, assenyaleu l''afirmació INCORRECTA:', 'Rèplica de la pregunta 4 de Terrassa 2026. L''article 147.4 CP exigeix denúncia de la persona agreujada per als delictes dels apartats 2 i 3 (fora dels casos de l''article 153).', 'plcatexamen_2026_terrassa', (select id from public.topics where slug = 'plcatexamen-2026-terrassa'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 147 i 153 Codi penal', 'Los delitos previstos en los dos apartados anteriores sólo serán perseguibles mediante denuncia de la persona agraviada o de su representante legal.', null, '75abae02e2ddca41054ee9d8f6f3a2d708e68befab3f661d189d10e9b70415f6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '75abae02e2ddca41054ee9d8f6f3a2d708e68befab3f661d189d10e9b70415f6')
  returning id
), o as (
