with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'A partir de quin excés sobre la velocitat permesa en via urbana es comet delicte segons l''article 379.1 CP?', 'Rèplica de la pregunta 20 de Terrassa 2026. Article 379.1 CP: 60 km/h en via urbana i 80 km/h en interurbana.', 'plcatexamen_2026_terrassa', (select id from public.topics where slug = 'plcatexamen-2026-terrassa'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 379.1 Codi penal', 'a velocidad superior en sesenta kilómetros por hora en vía urbana o en ochenta kilómetros por hora en vía interurbana a la permitida reglamentariamente', null, '30acfb7dfdb27f923feff31a5392b6e06088bf1fcbd05aeb94f32ec838d6e693', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '30acfb7dfdb27f923feff31a5392b6e06088bf1fcbd05aeb94f32ec838d6e693')
