with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una persona sap que s''està a punt de cometre un homicidi i, podent fer-ho, no avisa l''autoritat ni els seus agents. Segons l''article 450 CP:', 'Rèplica de la pregunta 27 de Terrassa 2026. L''article 450.2 CP castiga qui no acudeix a l''autoritat per impedir els delictes de l''apartat 1.', 'plcatexamen_2026_terrassa', (select id from public.topics where slug = 'plcatexamen-2026-terrassa'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 450.2 Codi penal', 'En las mismas penas incurrirá quien, pudiendo hacerlo, no acuda a la autoridad o a sus agentes para que impidan un delito de los previstos en el apartado anterior', null, '76d5e21330ce265a095c706da284ac831110e5a849e7b5ff5b9de5a559bdddcb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '76d5e21330ce265a095c706da284ac831110e5a849e7b5ff5b9de5a559bdddcb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
