with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina pena preveu el Codi penal per a qui, amb finalitat sexual, fa presenciar a un menor de setze anys actes de caràcter sexual, encara que no hi participi?', 'Rèplica de la pregunta 28 de Terrassa 2026. Article 182.1 CP vigent (la pena puja a un a tres anys si els actes constitueixen delicte contra la llibertat sexual, art. 182.2). L''examen citava l''article 183 bis, numeració anterior a la LO 10/2022: es pregunta per la versió vigent.', 'plcatexamen_2026_terrassa', (select id from public.topics where slug = 'plcatexamen-2026-terrassa'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 182.1 Codi penal', 'El que, con fines sexuales, haga presenciar a un menor de dieciséis años actos de carácter sexual, aunque el autor no participe en ellos, será castigado con una pena de prisión de seis meses a dos años.', null, '606028989b3bb836d22bf5c44c9f8c761c96c8bef5e6f575ce556aaac6188b13', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '606028989b3bb836d22bf5c44c9f8c761c96c8bef5e6f575ce556aaac6188b13')
  returning id
