with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin d''aquests actes és NUL DE PLE DRET segons l''article 47.1 de la Llei 39/2015?', 'L''article 47.1.b) declara nuls de ple dret els actes dictats per òrgan manifestament incompetent per raó de la matèria o del territori. La desviació de poder és causa d''anul·labilitat (art. 48.1), i els defectes de forma i el retard només ho són en determinats casos (art. 48.2 i 3).', 'plcat_t05_procediment_administratiu', (select id from public.topics where slug = 'plcat-t05-procediment-administratiu'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 47 Llei 39/2015', 'b) Los dictados por órgano manifiestamente incompetente por razón de la materia o del territorio.', null, '8a97233cb6b95a9b6ece1fd59085ed45211c2245808fbc75ddb95443fe7164d3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8a97233cb6b95a9b6ece1fd59085ed45211c2245808fbc75ddb95443fe7164d3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El que incorre en desviació de poder.', false), ('B', 'El dictat per un òrgan manifestament incompetent per raó de la matèria o del territori.', true), ('C', 'El que té un defecte de forma que no causa indefensió.', false), ('D', 'El que s''ha dictat fora del termini establert, si la naturalesa del termini no ho imposa.', false)) as v(label, body, ok)
)
