with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 48.1 de la Llei 39/2015, són anul·lables els actes de l''Administració que incorrin en:', 'L''article 48.1 declara anul·lables els actes que incorren en qualsevol infracció de l''ordenament, inclosa la desviació de poder; les altres opcions són causes de nul·litat de ple dret (art. 47.1).', 'plcat_t05_procediment_administratiu', (select id from public.topics where slug = 'plcat-t05-procediment-administratiu'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 48 Llei 39/2015', '1. Son anulables los actos de la Administración que incurran en cualquier infracción del ordenamiento jurídico, incluso la desviación de poder.', null, '713e8d6ef7b06132e04a4e0ed889adfa045d2fb83fc3e555edd84fdc220b6bcc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '713e8d6ef7b06132e04a4e0ed889adfa045d2fb83fc3e555edd84fdc220b6bcc')
