with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Si una sol·licitud d''iniciació no reuneix els requisits exigits, segons l''article 68.1 de la Llei 39/2015 s''ha de requerir l''interessat perquè l''esmeni en un termini de:', 'L''article 68.1 fixa un termini de deu dies per esmenar, amb l''advertiment de desistiment; es pot ampliar fins a cinc dies més fora dels procediments selectius o de concurrència competitiva (art. 68.2).', 'plcat_t05_procediment_administratiu', (select id from public.topics where slug = 'plcat-t05-procediment-administratiu'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 68 Llei 39/2015', 'se requerirá al interesado para que, en un plazo de diez días, subsane la falta o acompañe los documentos preceptivos, con indicación de que, si así no lo hiciera, se le tendrá por desistido de su petición', null, 'dc24b922f58f9172dd6c4c17b13e11544002d4f5279d02ce4bd1d2a302fd59e5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'dc24b922f58f9172dd6c4c17b13e11544002d4f5279d02ce4bd1d2a302fd59e5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quinze dies, amb indicació que la sol·licitud caducarà.', false), ('B', 'Cinc dies improrrogables.', false), ('C', 'Un mes, amb indicació que se li imposarà una sanció.', false), ('D', 'Deu dies, amb indicació que, si no ho fa, se''l tindrà per desistit de la petició.', true)) as v(label, body, ok)
)
