  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Del 50 % en total, no acumulables.', false), ('B', 'D''almenys el 20 % cadascuna, acumulables entre si i condicionades al desistiment o la renúncia de recursos en via administrativa.', true), ('C', 'Del 10 % cadascuna, sense condicions.', false), ('D', 'Del 20 % només si es paga dins dels cinc primers dies.', false)) as v(label, body, ok)
)
