insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 2/1986, de 13 de marzo, de Fuerzas y Cuerpos de Seguridad (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t06-forces-cossos-seguretat', 'Tema 6. La Llei orgànica 2/1986 de forces i cossos de seguretat: principis bàsics d''actuació i policies locals') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t06-forces-cossos-seguretat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 1 de la Llei orgànica 2/1986, de forces i cossos de seguretat, la seguretat pública és:', 'L''article 1.1 LOFCS declara la seguretat pública competència exclusiva de l''Estat i n''atribueix el manteniment al Govern; comunitats autònomes i corporacions locals hi participen en els termes previstos (art. 1.2 i 1.3).', 'plcat_t06_forces_cossos_seguretat', (select id from public.topics where slug = 'plcat-t06-forces-cossos-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Art. 1 LO 2/1986', '1. La Seguridad Pública es competencia exclusiva del Estado. Su mantenimiento corresponde al Gobierno de la Nación.', null, 'ef49464f7d36e6e4fa16fc13780d5610beeeb9ffda0f367425dea7e336d63606', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ef49464f7d36e6e4fa16fc13780d5610beeeb9ffda0f367425dea7e336d63606')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Competència compartida entre l''Estat i les comunitats autònomes, a parts iguals.', false), ('B', 'Competència exclusiva de l''Estat, i el seu manteniment correspon al Govern de la Nació.', true), ('C', 'Competència exclusiva de les comunitats autònomes amb policia pròpia.', false), ('D', 'Competència dels municipis de més de 20.000 habitants.', false)) as v(label, body, ok)
)
