with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un municipi de 7.500 habitants, per crear un cos de policia local cal, segons l''article 3.2 de la Llei 16/1991:', 'L''article 3.1 permet la policia local als municipis de més de 10.000 habitants. Per sota d''aquesta xifra, l''article 3.2 exigeix l''acord de la majoria absoluta del nombre legal de membres de la corporació i l''autorització del conseller (actualment, el d''Interior), amb informe previ de la Comissió de Coordinació.', 'plcat_t07_policies_locals_funcions', (select id from public.topics where slug = 'plcat-t07-policies-locals-funcions'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343'), 'Art. 3 Llei 16/1991', '2. En los Municipios de menos de 10.000 habitantes puede existir Policía local si acuerda su creación la mayoría absoluta del número legal de miembros de la correspondiente Corporación local y lo autoriza el Consejero de Gobernación, previo informe de la Comisión de Coordinación de las Policías Locales.', null, 'e85bfc74fb9930a53f2041aaa4d79743376c4fa4990d4b13ad23cf6b05b1c8f5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e85bfc74fb9930a53f2041aaa4d79743376c4fa4990d4b13ad23cf6b05b1c8f5')
  returning id
), o as (
