  select 'Sobre la forma de prestació del servei de policia local, quina afirmació és correcta segons l''article 1.3 de la Llei 16/1991?', 'L''article 1.3 imposa la gestió directa: les corporacions locals no poden constituir òrgans especials de gestió ni aprovar la concessió, l''arrendament ni cap altra forma de gestió indirecta del servei.', 'plcat_t07_policies_locals_funcions', (select id from public.topics where slug = 'plcat-t07-policies-locals-funcions'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343'), 'Art. 1.3 Llei 16/1991', '3. El servicio que compete a las Policías locales será prestado directamente por las respectivas Corporaciones locales, que no pueden constituir órganos especiales de gestión ni aprobar la concesión, el arrendamiento ni ninguna otra forma de gestión indirecta del servicio.', null, 'a58416ccd571fea4218b216ace381ae1b09895abc7d64489ee0906f33440618a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a58416ccd571fea4218b216ace381ae1b09895abc7d64489ee0906f33440618a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es pot prestar mitjançant concessió a una empresa de seguretat privada homologada.', false), ('B', 'Es pot prestar mitjançant un organisme autònom o una societat municipal creats a aquest efecte.', false), ('C', 'Es pot encarregar al consell comarcal mitjançant un contracte d''arrendament de serveis.', false), ('D', 'L''han de prestar directament les corporacions locals, que no poden aprovar-ne cap forma de gestió indirecta.', true)) as v(label, body, ok)
)
