with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Qui és el cap del cos de la policia local segons l''article 26.2 de la Llei 16/1991, en la redacció vigent?', 'L''article 26.2, modificat per la Llei 2/2021, estableix que és cap del cos el membre de la plantilla de més graduació i, si n''hi ha diversos de la mateixa graduació, el nomena l''alcalde amb criteris d''objectivitat, mèrit, capacitat i igualtat d''oportunitats.', 'plcat_t07_policies_locals_funcions', (select id from public.topics where slug = 'plcat-t07-policies-locals-funcions'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343'), 'Art. 26 Llei 16/1991', '2. Es jefe del cuerpo el miembro de la plantilla de mayor graduación; en caso de igualdad, corresponde al alcalde realizar el nombramiento, de acuerdo con los principios de objetividad, de mérito, de capacidad y de igualdad de oportunidades.', null, '23bdb2f1349a2ea514892d8b57dcbbb3de42264ff6efc880595c7bf25a0cba87', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '23bdb2f1349a2ea514892d8b57dcbbb3de42264ff6efc880595c7bf25a0cba87')
  returning id
), o as (
