with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Pel que fa al dret de vaga, l''article 38 de la Llei 16/1991 estableix que els policies locals:', 'L''article 38 prohibeix als policies locals el dret de vaga i també les accions substitutives o concertades destinades a alterar el funcionament normal dels serveis. La participació en vagues és falta molt greu (art. 48.1.k).', 'plcat_t08_policies_locals_estatut_disciplina', (select id from public.topics where slug = 'plcat-t08-policies-locals-estatut-disciplina'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343'), 'Art. 38 Llei 16/1991', 'Los Policías locales no pueden ejercer el derecho de huelga ni participar en acciones sustitutivas de éste o en actuaciones concertadas con la finalidad de alterar el funcionamiento normal de los servicios.', null, '81218a0285dc069d955312f72ad78438953c458ccfcf21c5ae706dd10a0997ac', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '81218a0285dc069d955312f72ad78438953c458ccfcf21c5ae706dd10a0997ac')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Poden exercir el dret de vaga si garanteixen uns serveis mínims del 50 %.', false), ('B', 'Poden exercir el dret de vaga amb autorització prèvia de l''alcalde.', false), ('C', 'Poden fer vaga, però no poden participar en accions substitutives.', false), ('D', 'No poden exercir el dret de vaga ni participar en accions substitutives o concertades per alterar el funcionament normal dels serveis.', true)) as v(label, body, ok)
)
