  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ddce8504df0b3f8ada414e9a46716c410e82e206774a982929b36d72938d296e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El cap del cos, a petició de l''interessat.', false), ('B', 'La Comissió de Policia de Catalunya.', false), ('C', 'L''alcalde, quan ho aconsellin circumstàncies especials.', true), ('D', 'El jutge degà del partit judicial.', false)) as v(label, body, ok)
)
