  select 'Un agent observa un defecte que compromet el funcionament normal de la seva arma. Segons l''article 12 del Decret 219/1996, ha de:', 'L''article 12 prohibeix modificar l''arma o afegir-hi elements i obliga a comunicar les anomalies al comandament i a abstenir-se de manipular-la.', 'plcat_t10_armament', (select id from public.topics where slug = 'plcat-t10-armament'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=129214'), 'Art. 12 Decret 219/1996', 'el titular de la guia ho comunicarà al comandament corresponent, i s''abstindrà de manipular o d''efectuar gestions particulars per reparar-ne les deficiències.', null, 'e1ad6b754fe6afe7d165e28a15171045cf77741b8a5f832bc147022fe11ebf31', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e1ad6b754fe6afe7d165e28a15171045cf77741b8a5f832bc147022fe11ebf31')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
