with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quan hi ha indicis de deficiències físiques, psíquiques o formatives que puguin comprometre el servei, la retirada cautelar de l''arma que ordena l''alcalde, segons l''article 17.1 del Decret 219/1996, té una durada:', 'L''article 17.1 limita la retirada cautelar a un període no superior a quinze dies; si les causes subsisteixen, es demanen informes d''especialistes perquè l''òrgan competent resolgui. La mesura ha de ser motivada (art. 17.2).', 'plcat_t10_armament', (select id from public.topics where slug = 'plcat-t10-armament'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=129214'), 'Art. 17 Decret 219/1996', 'l''alcalde o persona en qui delegui ordenarà la retirada de l''arma de foc, per un període no superior a quinze dies.', null, 'ebfe58a805dbabcbe996987905c0ae8479497382230c987af565b5a119a1db93', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ebfe58a805dbabcbe996987905c0ae8479497382230c987af565b5a119a1db93')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No superior a un mes.', false), ('B', 'No superior a tres mesos.', false), ('C', 'No superior a quinze dies.', true), ('D', 'Indefinida, fins que l''agent es jubili.', false)) as v(label, body, ok)
)
