with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 1.1 de la LO 4/2015, de protecció de la seguretat ciutadana, la salvaguarda de la seguretat ciutadana, com a bé jurídic de caràcter col·lectiu, és funció:', 'L''article 1.1 LOPSC qualifica la seguretat ciutadana com a requisit indispensable per exercir els drets i atribueix la seva salvaguarda a l''Estat.', 'plcat_t11_seguretat_ciutadana_1', (select id from public.topics where slug = 'plcat-t11-seguretat-ciutadana-1'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'Art. 1.1 LO 4/2015', 'y su salvaguarda, como bien jurídico de carácter colectivo, es función del Estado, con sujeción a la Constitución y a las Leyes.', null, '90e0a45c9f8c26ea55dd755c7384c2309d9c6e6d7db586a9a479b65165f9b9d9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '90e0a45c9f8c26ea55dd755c7384c2309d9c6e6d7db586a9a479b65165f9b9d9')
  returning id
