with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 2.2 de la LO 4/2015, queden fora de l''àmbit d''aplicació de la llei:', 'L''article 2.2 LOPSC exclou les prescripcions sobre el bon ordre dels espectacles i la protecció de persones i béns per acció administrativa ordinària, encara que hi intervinguin les forces de seguretat com a part del sistema preventiu habitual.', 'plcat_t11_seguretat_ciutadana_1', (select id from public.topics where slug = 'plcat-t11-seguretat-ciutadana-1'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'Art. 2.2 LO 4/2015', '2. En particular, quedan fuera del ámbito de aplicación de esta Ley las prescripciones que tienen por objeto velar por el buen orden de los espectáculos y la protección de las personas y bienes a través de una acción administrativa ordinaria', null, '86cf3f94983b4b48fb5fc76397a33a98e236ce9127ee49996673fa1f80896d2d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '86cf3f94983b4b48fb5fc76397a33a98e236ce9127ee49996673fa1f80896d2d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Totes les actuacions de les policies locals.', false), ('B', 'Les manifestacions comunicades prèviament.', false), ('C', 'Les prescripcions que tenen per objecte vetllar pel bon ordre dels espectacles mitjançant una acció administrativa ordinària, encara que comporti la intervenció de les forces de seguretat com a element del sistema preventiu habitual.', true), ('D', 'Les actuacions en matèria de trànsit en vies urbanes, en tots els casos.', false)) as v(label, body, ok)
)
