with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 21 de la LO 4/2015, les mesures de seguretat extraordinàries (tancament o desallotjament de locals, prohibició del pas, evacuació d''immobles...) les poden adoptar els agents de l''autoritat:', 'L''article 21 LOPSC atribueix aquestes mesures a les autoritats en situacions d''emergència, però permet que les adoptin els agents si la urgència ho fa imprescindible, fins i tot amb ordres verbals.', 'plcat_t12_seguretat_ciutadana_2', (select id from public.topics where slug = 'plcat-t12-seguretat-ciutadana-2'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'Art. 21 LO 4/2015', 'Dichas medidas podrán adoptarse por los agentes de la autoridad si la urgencia de la situación lo hiciera imprescindible, incluso mediante órdenes verbales.', null, '426bf92731b6692341b2edbbebb5b1ceede31e91a423fe4b4fb0efbb5d543d54', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '426bf92731b6692341b2edbbebb5b1ceede31e91a423fe4b4fb0efbb5d543d54')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només amb autorització judicial prèvia.', false), ('B', 'Només per escrit i amb l''autorització del delegat del Govern.', false), ('C', 'Si la urgència de la situació ho fa imprescindible, fins i tot mitjançant ordres verbals.', true), ('D', 'En cap cas: són competència exclusiva de les autoritats.', false)) as v(label, body, ok)
)
