insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto de 14 de septiembre de 1882, Ley de Enjuiciamiento Criminal (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t13-policia-judicial-detencio', 'Tema 13. La Llei d''enjudiciament criminal: policia judicial, detenció i drets de la persona detinguda') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t13-policia-judicial-detencio' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 282 de la Llei d''enjudiciament criminal, és obligació de tots els que componen la policia judicial:', 'L''article 282 LECrim fixa l''objecte de la policia judicial: esbrinar els delictes públics, practicar les diligències per comprovar-los i descobrir els delinqüents, i recollir efectes i proves del delicte, posant-los a disposició judicial.', 'plcat_t13_policia_judicial_detencio', (select id from public.topics where slug = 'plcat-t13-policia-judicial-detencio'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 282 LECrim', 'averiguar los delitos públicos que se cometieren en su territorio o demarcación; practicar, según sus atribuciones, las diligencias necesarias para comprobarlos y descubrir a los delincuentes', null, '999279f9dcdbb7f04326ab72de7718a1087b69c600addf2eaf1ebf0dcad72103', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '999279f9dcdbb7f04326ab72de7718a1087b69c600addf2eaf1ebf0dcad72103')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Jutjar els delictes lleus comesos al seu territori.', false), ('B', 'Esbrinar els delictes públics comesos al seu territori, practicar les diligències necessàries per comprovar-los i descobrir els delinqüents, i recollir els efectes, instruments o proves del delicte.', true), ('C', 'Dictar ordres de presó provisional quan hi ha risc de fuga.', false), ('D', 'Formular l''acusació en el judici oral.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-local');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 282 de la LECrim, quan les víctimes entren en contacte amb la policia judicial, aquesta:', 'L''article 282 LECrim obliga la policia judicial a complir els deures d''informació a les víctimes i a valorar les seves circumstàncies per determinar provisionalment les mesures de protecció, sens perjudici de la decisió judicial.', 'plcat_t13_policia_judicial_detencio', (select id from public.topics where slug = 'plcat-t13-policia-judicial-detencio'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 282 LECrim', 'Asimismo, llevarán a cabo una valoración de las circunstancias particulares de las víctimas para determinar provisionalmente qué medidas de protección deben ser adoptadas para garantizarles una protección adecuada, sin perjuicio de la decisión final que corresponderá adoptar al Juez o Tribunal.', null, '40fd5e78fc52d55a6f4d15183c6d399fb40d21e2fff5d2682323105b1bbe13e7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '40fd5e78fc52d55a6f4d15183c6d399fb40d21e2fff5d2682323105b1bbe13e7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ha d''adoptar amb caràcter definitiu les mesures de protecció necessàries.', false), ('B', 'No pot fer cap valoració, perquè és competència exclusiva del jutge.', false), ('C', 'Ha de derivar-les sempre als serveis socials municipals.', false), ('D', 'Ha de fer una valoració de les seves circumstàncies particulars per determinar provisionalment les mesures de protecció, sens perjudici de la decisió final del jutge o tribunal.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-local');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 284.2 de la LECrim, quan no hi ha autor conegut del delicte, la policia judicial conserva l''atestat sense enviar-lo al jutjat, LLEVAT que:', 'L''article 284.2 LECrim obliga a remetre l''atestat sense autor conegut en els delictes contra la vida, la integritat física, la llibertat i indemnitat sexuals o de corrupció; quan es practica alguna diligència amb resultat passades setanta-dues hores; o quan ho demanen el fiscal o el jutge.', 'plcat_t13_policia_judicial_detencio', (select id from public.topics where slug = 'plcat-t13-policia-judicial-detencio'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 284.2 LECrim', 'a) Que se trate de delitos contra la vida, contra la integridad física, contra la libertad e indemnidad sexuales o de delitos relacionados con la corrupción;', null, 'fb582970c891ff5ad12e151093e87031c47dc404aa32b90ecf88f6bd8184442d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'fb582970c891ff5ad12e151093e87031c47dc404aa32b90ecf88f6bd8184442d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es tracti de delictes contra la vida, la integritat física, la llibertat i indemnitat sexuals o relacionats amb la corrupció.', true), ('B', 'Es tracti de qualsevol delicte contra el patrimoni.', false), ('C', 'La víctima no hagi demanat expressament la remissió.', false), ('D', 'Hagin passat vint-i-quatre hores des de l''obertura de l''atestat, encara que no hi hagi cap diligència nova.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-local');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 292 de la LECrim, els funcionaris de policia judicial han d''estendre un atestat de les diligències que practiquin, en el qual han d''especificar:', 'L''article 292 LECrim descriu el contingut de l''atestat i obliga a remetre-hi un informe de detencions anteriors i requisitòries que constin a les bases de dades.', 'plcat_t13_policia_judicial_detencio', (select id from public.topics where slug = 'plcat-t13-policia-judicial-detencio'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 292 LECrim', 'en el cual especificarán con la mayor exactitud los hechos por ellos averiguados, insertando las declaraciones e informes recibidos y anotando todas las circunstancias que hubiesen observado y pudiesen ser prueba o indicio del delito.', null, '0cbeef90b1a1027e686b7069b9ace7ee24ea84e07a793c3ac57b8be5f9bcebe3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0cbeef90b1a1027e686b7069b9ace7ee24ea84e07a793c3ac57b8be5f9bcebe3')
  returning id
), o as (
