  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 295 de la LECrim, els funcionaris de policia judicial no poden deixar passar més de quant temps sense donar coneixement a l''autoritat judicial o al Ministeri Fiscal de les diligències practicades, llevat de força major i del supòsit de l''article 284.2?', 'L''article 295 LECrim fixa un màxim de vint-i-quatre hores per comunicar les diligències, amb l''excepció de força major i dels atestats sense autor conegut (art. 284.2).', 'plcat_t13_policia_judicial_detencio', (select id from public.topics where slug = 'plcat-t13-policia-judicial-detencio'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 295 LECrim', 'En ningún caso los funcionarios de Policía Judicial podrán dejar transcurrir más de veinticuatro horas sin dar conocimiento a la autoridad judicial o al Ministerio Fiscal de las diligencias que hubieran practicado', null, '11a3ea5ea611db8e763bb6af88314abf5bde515680538acf25eb87beb7a402b4', false
