with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 1 de la LO 6/1984, reguladora del procediment d''habeas corpus, aquest procediment permet obtenir:', 'L''article 1 LOHC defineix l''objecte de l''habeas corpus: la posada immediata a disposició judicial de qualsevol persona detinguda il·legalment.', 'plcat_t14_entrada_registre_habeas_corpus', (select id from public.topics where slug = 'plcat-t14-entrada-registre-habeas-corpus'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'Art. 1 LO 6/1984', 'se podrá obtener la inmediata puesta a disposición de la Autoridad judicial competente, de cualquier persona detenida ilegalmente.', null, '3a9ca8ada2d000a36529caf4cd095f681b8212b9c40695818dce165863ce4c47', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3a9ca8ada2d000a36529caf4cd095f681b8212b9c40695818dce165863ce4c47')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La indemnització per una detenció il·legal.', false), ('B', 'La revisió d''una sentència penal ferma.', false), ('C', 'La posada immediata a disposició de l''autoritat judicial competent de qualsevol persona detinguda il·legalment.', true), ('D', 'L''anul·lació d''una sanció administrativa.', false)) as v(label, body, ok)
)
