with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin d''aquests supòsits NO és un cas de detenció il·legal segons l''article 1 de la LO 6/1984?', 'L''article 1 LOHC considera il·legals les detencions sense supòsit legal o sense formalitats, els internaments il·lícits, les que superen el termini legal i les que no respecten els drets del detingut.', 'plcat_t14_entrada_registre_habeas_corpus', (select id from public.topics where slug = 'plcat-t14-entrada-registre-habeas-corpus'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'Art. 1 LO 6/1984', 'd) Las privadas de libertad a quienes no les sean respetados los derechos que la Constitución y las leyes procesales garantizan a toda persona detenida.', null, 'aacffbec56a51606b766e5e0cfd08ef740de87aca7f6dd19ca1e8d3c1177b9bd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'aacffbec56a51606b766e5e0cfd08ef740de87aca7f6dd19ca1e8d3c1177b9bd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La detenció sense que concorrin els supòsits legals.', false), ('B', 'La detenció per un termini superior al fixat a les lleis sense posada en llibertat o a disposició judicial.', false), ('C', 'La detenció d''una persona sorpresa en flagrant delicte, informada dels seus drets i lliurada al jutge dins de termini.', true), ('D', 'La detenció en què no es respecten els drets que la Constitució i les lleis processals garanteixen al detingut.', false)) as v(label, body, ok)
)
