insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 10/1995, de 23 de noviembre, del Código Penal (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t15-codi-penal-persones', 'Tema 15. Codi penal (I): lesions, delictes contra la llibertat, tortures i delictes contra la llibertat sexual') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t15-codi-penal-persones' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 147.1 del Codi penal, perquè una lesió constitueixi el delicte de lesions del tipus bàsic, ha de requerir objectivament per a la seva sanitat:', 'L''article 147.1 CP exigeix, a més de la primera assistència facultativa, tractament mèdic o quirúrgic; la simple vigilància o seguiment del curs de la lesió no és tractament mèdic.', 'plcat_t15_codi_penal_persones', (select id from public.topics where slug = 'plcat-t15-codi-penal-persones'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 147.1 CP', 'siempre que la lesión requiera objetivamente para su sanidad, además de una primera asistencia facultativa, tratamiento médico o quirúrgico.', null, '61df91bc3a623a564a1da3a3ba93df94fbb0c36863201a4c4357bc85bbe1b707', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '61df91bc3a623a564a1da3a3ba93df94fbb0c36863201a4c4357bc85bbe1b707')
  returning id
