with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 178.1 del Codi penal, quan s''entén que hi ha consentiment en l''àmbit de la llibertat sexual?', 'L''article 178.1 CP defineix el consentiment com el manifestat lliurement mitjançant actes que expressin de manera clara la voluntat de la persona.', 'plcat_t15_codi_penal_persones', (select id from public.topics where slug = 'plcat-t15-codi-penal-persones'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 178.1 CP', 'Sólo se entenderá que hay consentimiento cuando se haya manifestado libremente mediante actos que, en atención a las circunstancias del caso, expresen de manera clara la voluntad de la persona.', null, '16ec358389e81c5f56d64a896f9731c223d43618e0889da4f482a20cbedf1459', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '16ec358389e81c5f56d64a896f9731c223d43618e0889da4f482a20cbedf1459')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan la persona no s''hi ha oposat expressament.', false), ('B', 'Només quan s''ha manifestat lliurement mitjançant actes que, segons les circumstàncies, expressin de manera clara la voluntat de la persona.', true), ('C', 'Quan la persona no ha presentat resistència física.', false), ('D', 'Quan hi ha una relació de parella prèvia.', false)) as v(label, body, ok)
)
