with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 179.1 del Codi penal, quan l''agressió sexual consisteix en accés carnal per via vaginal, anal o bucal, o introducció de membres corporals o objectes per alguna de les dues primeres vies, el responsable és castigat com a reu de:', 'L''article 179.1 CP castiga la violació amb presó de quatre a dotze anys; si es comet amb violència o intimidació o amb la voluntat de la víctima anul·lada, la pena és de sis a dotze anys (art. 179.2).', 'plcat_t15_codi_penal_persones', (select id from public.topics where slug = 'plcat-t15-codi-penal-persones'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 179 CP', 'el responsable será castigado como reo de violación con la pena de prisión de cuatro a doce años.', null, '2ad24fd0b319f8684100cf064df5523c6a16cba6fb8aa454aa5d079bfcf5a664', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2ad24fd0b319f8684100cf064df5523c6a16cba6fb8aa454aa5d079bfcf5a664')
  returning id
), o as (
