with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 183 bis del Codi penal, el lliure consentiment del menor de setze anys exclou la responsabilitat penal pels delictes del capítol corresponent quan:', 'L''article 183 bis CP exclou la responsabilitat penal pel consentiment lliure del menor de setze anys quan l''autor és una persona pròxima per edat i grau de desenvolupament o maduresa, llevat dels casos de l''article 178.2 (violència, intimidació, abús...).', 'plcat_t15_codi_penal_persones', (select id from public.topics where slug = 'plcat-t15-codi-penal-persones'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 183 bis CP', 'el libre consentimiento del menor de dieciséis años excluirá la responsabilidad penal por los delitos previstos en este capítulo cuando el autor sea una persona próxima al menor por edad y grado de desarrollo o madurez física y psicológica.', null, '4b708e1e8a799b5a0c95c64a2c116e0640887f163b24c4159f66ebca7030549f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4b708e1e8a799b5a0c95c64a2c116e0640887f163b24c4159f66ebca7030549f')
  returning id
