with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 234.1 del Codi penal, qui, amb ànim de lucre, pren les coses mobles alienes sense la voluntat del seu propietari, si la quantia excedeix de 400 euros, comet un delicte de:', 'L''article 234.1 CP defineix el furt (presó de sis a divuit mesos si la quantia supera 400 euros); si no els supera, és furt lleu amb multa d''un a tres mesos (art. 234.2).', 'plcat_t16_codi_penal_patrimoni_salut_seguretat_viaria', (select id from public.topics where slug = 'plcat-t16-codi-penal-patrimoni-salut-seguretat-viaria'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 234 CP', '1. El que, con ánimo de lucro, tomare las cosas muebles ajenas sin la voluntad de su dueño será castigado, como reo de hurto, con la pena de prisión de seis a dieciocho meses si la cuantía de lo sustraído excediese de 400 euros.', null, 'a33bc206537a6d69461f984773497c5f7d3bfaaf1e4f52147aac37e59b4f4a83', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a33bc206537a6d69461f984773497c5f7d3bfaaf1e4f52147aac37e59b4f4a83')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Furt, castigat amb presó de sis a divuit mesos.', true), ('B', 'Robatori amb força, castigat amb presó d''un a tres anys.', false), ('C', 'Apropiació indeguda.', false), ('D', 'Furt lleu, castigat amb multa d''un a tres mesos.', false)) as v(label, body, ok)
)
