with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 234.2 del Codi penal, un furt de quantia no superior a 400 euros es castiga amb la pena del furt bàsic (presó de sis a divuit mesos) quan:', 'L''article 234.2 CP eleva el furt lleu a la pena del furt bàsic si hi ha almenys tres condemnes executòries prèvies per delictes de la mateixa naturalesa (almenys una lleu); no es tenen en compte els antecedents cancel·lats o que s''haurien d''haver cancel·lat.', 'plcat_t16_codi_penal_patrimoni_salut_seguretat_viaria', (select id from public.topics where slug = 'plcat-t16-codi-penal-patrimoni-salut-seguretat-viaria'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 234.2 CP', 'en el caso de que el culpable hubiera sido condenado ejecutoriamente al menos por tres delitos de la misma naturaleza, comprendidos en este Título, y siendo al menos uno de ellos leve', null, '0dc0712a724a3e79d80a2b894f1829dcd133631d8ce56f1218deb2a353cd77c4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0dc0712a724a3e79d80a2b894f1829dcd133631d8ce56f1218deb2a353cd77c4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El culpable és estranger sense residència legal.', false), ('B', 'El furt es comet de nit.', false), ('C', 'El culpable ha estat condemnat executòriament almenys per tres delictes de la mateixa naturalesa del títol, i almenys un d''ells és lleu.', true), ('D', 'El culpable té qualsevol antecedent penal, encara que estigui cancel·lat.', false)) as v(label, body, ok)
)
