  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 237 del Codi penal, què diferencia el robatori del furt?', 'L''article 237 CP defineix el robatori per l''apoderament amb força en les coses o amb violència o intimidació en les persones.', 'plcat_t16_codi_penal_patrimoni_salut_seguretat_viaria', (select id from public.topics where slug = 'plcat-t16-codi-penal-patrimoni-salut-seguretat-viaria'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 237 CP', 'empleando fuerza en las cosas para acceder o abandonar el lugar donde éstas se encuentran o violencia o intimidación en las personas', null, '795bcb35c728fb9700b3d5df9cdc9bfca7bdf84450275faae503b27461363813', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '795bcb35c728fb9700b3d5df9cdc9bfca7bdf84450275faae503b27461363813')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El valor de la cosa sostreta, que en el robatori ha de superar 400 euros.', false), ('B', 'L''ús de força en les coses per accedir o abandonar el lloc on són, o de violència o intimidació en les persones.', true), ('C', 'Que en el robatori la cosa és un immoble.', false), ('D', 'Que en el robatori no hi ha ànim de lucre.', false)) as v(label, body, ok)
)
