with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina d''aquestes circumstàncies NO és constitutiva de robatori amb força en les coses segons l''article 238 del Codi penal?', 'L''article 238 CP enumera l''escalada, el trencament de paret, sostre o terra o la fractura de porta o finestra, la fractura de mobles tancats, l''ús de claus falses i la inutilització d''alarmes. Entrar per una porta oberta no és cap d''aquestes circumstàncies.', 'plcat_t16_codi_penal_patrimoni_salut_seguretat_viaria', (select id from public.topics where slug = 'plcat-t16-codi-penal-patrimoni-salut-seguretat-viaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 238 CP', '1.º Escalamiento. 2.º Rompimiento de pared, techo o suelo, o fractura de puerta o ventana.', null, 'e535213e21a2814b1fc1144029a49c1189fff37f371e8bc75020d6b334a91f06', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e535213e21a2814b1fc1144029a49c1189fff37f371e8bc75020d6b334a91f06')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''escalada.', false), ('B', 'L''ús de claus falses.', false), ('C', 'La inutilització de sistemes específics d''alarma o guarda.', false), ('D', 'Aprofitar que la porta és oberta per entrar i agafar un objecte.', true)) as v(label, body, ok)
)
