with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 24.2 del Codi penal, a efectes penals es considera funcionari públic:', 'L''article 24.2 CP adopta un concepte funcional de funcionari públic; qui té comandament o exerceix jurisdicció pròpia és autoritat (art. 24.1).', 'plcat_t17_codi_penal_ordre_public_funcionaris', (select id from public.topics where slug = 'plcat-t17-codi-penal-ordre-public-funcionaris'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 24 CP', '2. Se considerará funcionario público todo el que por disposición inmediata de la Ley o por elección o por nombramiento de autoridad competente participe en el ejercicio de funciones públicas.', null, 'ea26f386044c661d7d10a3aa4549b98607f081fd23f276bc95eaf59739991b25', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ea26f386044c661d7d10a3aa4549b98607f081fd23f276bc95eaf59739991b25')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només qui ha superat una oposició i ha pres possessió d''una plaça de carrera.', false), ('B', 'Qui, per disposició immediata de la llei, per elecció o per nomenament d''autoritat competent, participa en l''exercici de funcions públiques.', true), ('C', 'Qualsevol treballador d''una empresa pública.', false), ('D', 'Només qui té comandament o exerceix jurisdicció pròpia.', false)) as v(label, body, ok)
)
