  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Qui, per si sol o com a membre d''una corporació, tribunal o òrgan col·legiat, té comandament o exerceix jurisdicció pròpia.', true), ('B', 'Qualsevol agent de policia uniformat.', false), ('C', 'Qualsevol funcionari amb més de deu anys d''antiguitat.', false), ('D', 'Només els jutges i magistrats.', false)) as v(label, body, ok)
