insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t19-violencia-masclista', 'Tema 19. Violència masclista i domèstica: Llei 5/2008, LO 1/2004 i ordre de protecció') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t19-violencia-masclista' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 1.1 de la LO 1/2004, de mesures de protecció integral contra la violència de gènere, aquesta llei actua contra la violència exercida sobre les dones per part de:', 'L''article 1.1 LOVG limita l''àmbit a la violència exercida per cònjuges o excònjuges i per parelles o exparelles, fins i tot sense convivència. La Llei catalana 5/2008 té un concepte més ampli de violència masclista.', 'plcat_t19_violencia_masclista', (select id from public.topics where slug = 'plcat-t19-violencia-masclista'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760'), 'Art. 1.1 LO 1/2004', 'se ejerce sobre éstas por parte de quienes sean o hayan sido sus cónyuges o de quienes estén o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia.', null, '60415fa4059312995e966823b468d6f806601f921651b7ec3469fd9d0e62b65f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '60415fa4059312995e966823b468d6f806601f921651b7ec3469fd9d0e62b65f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Qualsevol membre de la seva família.', false), ('B', 'Qui són o han estat els seus cònjuges o qui hi estan o hi han estat lligats per relacions similars d''afectivitat, fins i tot sense convivència.', true), ('C', 'Qualsevol home, en qualsevol àmbit.', false), ('D', 'Només els cònjuges amb qui conviuen.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-local');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 1.3 de la LO 1/2004, la violència de gènere comprèn:', 'L''article 1.3 LOVG defineix la violència de gènere de manera àmplia; l''apartat 4 hi inclou la violència vicària sobre familiars o persones properes menors d''edat.', 'plcat_t19_violencia_masclista', (select id from public.topics where slug = 'plcat-t19-violencia-masclista'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760'), 'Art. 1.3 LO 1/2004', '3. La violencia de género a que se refiere la presente Ley comprende todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad.', null, '7086acbf8b8b4764ebec9802e36c0f20c1a14b21d0946f4c3ce9e0d6bbc048ec', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7086acbf8b8b4764ebec9802e36c0f20c1a14b21d0946f4c3ce9e0d6bbc048ec')
