  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 4 de la Llei 5/2008, la conducta o omissió que produeix en una dona una desvaloració o un patiment mitjançant amenaces, humiliació, vexacions, insults, aïllament o altres limitacions de la seva llibertat és:', 'L''article 4.2.b) de la Llei 5/2008 defineix la violència psicològica i hi inclou l''amenaça o causació de violència contra l''entorn afectiu de la dona, especialment els fills.', 'plcat_t19_violencia_masclista', (select id from public.topics where slug = 'plcat-t19-violencia-masclista'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294'), 'Art. 4 Llei 5/2008', 'b) Violencia psicológica: comprende toda conducta u omisión que produce en una mujer una desvaloración o un sufrimiento', null, '7c542ab7a9bbfaa916a227cf946ac5c725f34a2d153fe9577f62b1f79601a95b', false
