  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 7 del text refós de la Llei de trànsit, circulació de vehicles de motor i seguretat viària (RDL 6/2015), correspon als municipis:', 'L''article 7.a) TRLTSV atribueix als municipis la gestió i la disciplina del trànsit a les vies urbanes de la seva titularitat, inclosa la denúncia i la sanció de les infraccions quan no estigui atribuïda a una altra administració.', 'plcat_t20_transit_seguretat_viaria', (select id from public.topics where slug = 'plcat-t20-transit-seguretat-viaria'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722'), 'Art. 7 TRLTSV', 'a) La regulación, ordenación, gestión, vigilancia y disciplina, por medio de agentes propios, del tráfico en las vías urbanas de su titularidad', null, '3bb8e0f538f2f8cd46397427f4488afb2832c89d79618f58ee4f12282f94915d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3bb8e0f538f2f8cd46397427f4488afb2832c89d79618f58ee4f12282f94915d')
  returning id
), o as (
