  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 105.1 del TRLTSV, l''autoritat encarregada de la gestió del trànsit pot retirar un vehicle de la via i dipositar-lo si l''obligat no ho fa:', 'L''article 105.1 TRLTSV enumera els casos de retirada i dipòsit, el primer dels quals és el perill, la pertorbació greu de la circulació o el deteriorament d''un servei o patrimoni públic.', 'plcat_t20_transit_seguretat_viaria', (select id from public.topics where slug = 'plcat-t20-transit-seguretat-viaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722'), 'Art. 105 TRLTSV', 'a) Siempre que constituya peligro, cause graves perturbaciones a la circulación de vehículos o peatones o deteriore algún servicio o patrimonio público.', null, '42207a45efd75f5a5aac79f1a537077f745155878da2aab765f4f385b4d5b334', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '42207a45efd75f5a5aac79f1a537077f745155878da2aab765f4f385b4d5b334')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només si porta més d''un mes estacionat al mateix lloc.', false), ('B', 'Només amb autorització judicial.', false), ('C', 'Sempre que constitueixi un perill, causi pertorbacions greus a la circulació de vehicles o vianants o deteriori algun servei o patrimoni públic.', true), ('D', 'Només si el titular té multes pendents.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-local');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 106.1.b) del TRLTSV, l''Administració pot ordenar el trasllat d''un vehicle a un centre autoritzat de tractament quan:', 'L''article 106.1 TRLTSV preveu el tractament residual, entre d''altres casos, si el vehicle porta més d''un mes estacionat al mateix lloc amb desperfectes que n''impedeixen el desplaçament o sense plaques, o si en fa més de dos que està dipositat sense al·legacions del titular.', 'plcat_t20_transit_seguretat_viaria', (select id from public.topics where slug = 'plcat-t20-transit-seguretat-viaria'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11722'), 'Art. 106 TRLTSV', 'b) Cuando permanezca estacionado por un período superior a un mes en el mismo lugar y presente desperfectos que hagan imposible su desplazamiento por sus propios medios o le falten las placas de matrícula.', null, '05f010b6f4df0e5d0d86ab03a2ef527eb44a1de5abbdcd7766fed4ae0fda39ba', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '05f010b6f4df0e5d0d86ab03a2ef527eb44a1de5abbdcd7766fed4ae0fda39ba')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Roman estacionat per un període superior a un mes al mateix lloc i presenta desperfectes que impossibiliten el seu desplaçament per mitjans propis o li falten les plaques de matrícula.', true), ('B', 'Roman estacionat més de quinze dies al mateix lloc, sigui quin sigui el seu estat.', false), ('C', 'El titular té més de tres multes impagades.', false), ('D', 'Ha passat la ITV desfavorable.', false)) as v(label, body, ok)
)
