insert into public.topics (slug, title) values ('plcat-t20-transit-seguretat-viaria', 'Tema 20. Trànsit i seguretat viària: text refós de la Llei de trànsit, Reglament general de circulació i Reglament general de conductors') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t20-transit-seguretat-viaria' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 20 del Reglament general de circulació, la taxa d''alcohol màxima amb caràcter general per als conductors de vehicles i de bicicletes és de:', 'L''article 20 RGC fixa la taxa general (0,5 g/l en sang o 0,25 mg/l en aire espirat) i una taxa reduïda (0,3 g/l o 0,15 mg/l) per a professionals i per als conductors durant els dos primers anys de permís.', 'plcat_t20_transit_seguretat_viaria', (select id from public.topics where slug = 'plcat-t20-transit-seguretat-viaria'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514'), 'Art. 20 RGC', 'con una tasa de alcohol en sangre superior a 0,5 gramos por litro, o de alcohol en aire espirado superior a 0,25 miligramos por litro.', null, '41751184946f3a6608c69f5405d21a9ae3d7e7f0876cf5f63a6b71b16c06d39f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '41751184946f3a6608c69f5405d21a9ae3d7e7f0876cf5f63a6b71b16c06d39f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '0,3 g/l en sang o 0,15 mg/l en aire espirat.', false), ('B', '0,5 g/l en sang o 0,25 mg/l en aire espirat.', true), ('C', '0,8 g/l en sang o 0,4 mg/l en aire espirat.', false), ('D', '1,2 g/l en sang o 0,6 mg/l en aire espirat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-local');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 20 del RGC, durant quant de temps després d''obtenir el permís o la llicència no poden superar els conductors una taxa d''alcohol de 0,15 mg/l en aire espirat?', 'L''article 20 RGC aplica la taxa de 0,3 g/l en sang o 0,15 mg/l en aire espirat als conductors durant els dos anys següents a l''obtenció del permís o la llicència.', 'plcat_t20_transit_seguretat_viaria', (select id from public.topics where slug = 'plcat-t20-transit-seguretat-viaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514'), 'Art. 20 RGC', 'Los conductores de cualquier vehículo no podrán superar la tasa de alcohol en sangre de 0,3 gramos por litro ni de alcohol en aire espirado de 0,15 miligramos por litro durante los dos años siguientes a la obtención del permiso o licencia que les habilita para conducir.', null, '25d2fb2699e2ba5e56262865efa15d43e4a28e087e1b039975207a3509f3a424', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '25d2fb2699e2ba5e56262865efa15d43e4a28e087e1b039975207a3509f3a424')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un any.', false), ('B', 'Tres anys.', false), ('C', 'Cinc anys.', false), ('D', 'Dos anys.', true)) as v(label, body, ok)
)
