with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 20 del RGC, quin d''aquests conductors té una taxa màxima de 0,3 g/l en sang o 0,15 mg/l en aire espirat, encara que tingui el permís des de fa anys?', 'L''article 20 RGC aplica la taxa reduïda als conductors de vehicles de mercaderies de més de 3.500 kg, de viatgers de més de nou places, de servei públic, de transport escolar i de menors, de mercaderies perilloses, de servei d''urgència o de transports especials.', 'plcat_t20_transit_seguretat_viaria', (select id from public.topics where slug = 'plcat-t20-transit-seguretat-viaria'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514'), 'Art. 20 RGC', 'al transporte escolar y de menores, al de mercancías peligrosas o de servicio de urgencia o transportes especiales', null, '4b6c04b4f68e64193aea123a535028e300fcc5b3ff7a4ac42055731a52fa4b69', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4b6c04b4f68e64193aea123a535028e300fcc5b3ff7a4ac42055731a52fa4b69')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El conductor d''un vehicle de transport escolar.', true), ('B', 'El conductor d''un turisme particular.', false), ('C', 'El conductor d''una bicicleta.', false), ('D', 'El conductor d''una motocicleta de més de 125 cc.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
