with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 21 del RGC, quin d''aquests usuaris NO poden sotmetre els agents a les proves d''alcoholèmia?', 'L''article 21 RGC obliga tots els conductors i també els altres usuaris implicats en un accident; els agents poden sotmetre a les proves els implicats com a possibles responsables, els conductors amb símptomes, els denunciats per infraccions i els requerits en controls preventius.', 'plcat_t20_transit_seguretat_viaria', (select id from public.topics where slug = 'plcat-t20-transit-seguretat-viaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514'), 'Art. 21 RGC', 'a) A cualquier usuario de la vía o conductor de vehículo implicado directamente como posible responsable en un accidente de circulación.', null, '1cfc87f673b2670d8a34005bea5534d2d08c4fc1a14f2badf0afad542fc30b8d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1cfc87f673b2670d8a34005bea5534d2d08c4fc1a14f2badf0afad542fc30b8d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un conductor implicat directament com a possible responsable en un accident.', false), ('B', 'Un conductor denunciat per una infracció de les normes del reglament.', false), ('C', 'Un vianant que passeja per la vorera sense estar implicat en cap accident.', true), ('D', 'Un conductor requerit en un control preventiu d''alcoholèmia ordenat per l''autoritat.', false)) as v(label, body, ok)
)
