insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 11/2009, de 6 de julio, de regulación administrativa de los espectáculos públicos y las actividades recreativas (Cataluña) (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t21-espectacles-publics', 'Tema 21. La Llei 11/2009 d''espectacles públics i activitats recreatives: competències, control i règim sancionador') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t21-espectacles-publics' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 1 de la Llei 11/2009, de regulació administrativa dels espectacles públics i les activitats recreatives, l''objecte de la llei és:', 'L''article 1 de la Llei 11/2009 fixa l''objecte: el règim jurídic dels espectacles públics, de les activitats recreatives i dels establiments i espais oberts al públic, i la seva intervenció administrativa.', 'plcat_t21_espectacles_publics', (select id from public.topics where slug = 'plcat-t21-espectacles-publics'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856'), 'Art. 1 Llei 11/2009', 'El objeto de la presente ley es establecer el régimen jurídico de los espectáculos públicos, las actividades recreativas, así como los establecimientos y los espacios abiertos al público donde se llevan a cabo dichas actividades, y regular su intervención administrativa.', null, '55e80b98552d5633d277e69fd058fdf150605a6b6b7e0d00f1d59e875d4de703', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '55e80b98552d5633d277e69fd058fdf150605a6b6b7e0d00f1d59e875d4de703')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Regular el dret de reunió i manifestació a Catalunya.', false), ('B', 'Regular la seguretat privada en els locals d''oci.', false), ('C', 'Regular les infraccions de convivència a la via pública.', false), ('D', 'Establir el règim jurídic dels espectacles públics, les activitats recreatives i els establiments i espais oberts al públic on es fan, i regular-ne la intervenció administrativa.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-local');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 3 de la Llei 11/2009, les activitats musicals que congreguen un públic amb l''objectiu principal de fer-lo participar en l''activitat o d''oferir-li el consum de productes o serveis amb finalitats d''oci són:', 'L''article 3.1.b) de la Llei 11/2009 defineix les activitats recreatives; els espectacles públics es caracteritzen perquè el públic hi acudeix per contemplar representacions o actuacions (art. 3.1.a).', 'plcat_t21_espectacles_publics', (select id from public.topics where slug = 'plcat-t21-espectacles-publics'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856'), 'Art. 3 Llei 11/2009', 'b) Actividades recreativas: actividades musicales que congregan a un público con el objetivo principal de hacerle participar en la actividad o de ofrecerle el consumo de productos o servicios con finalidades de ocio, entretenimiento o diversión.', null, 'b9d2999a70eb53c7a722a5d9e676eb5f6b1800b7d740ef46a4db440f5a13a3ed', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b9d2999a70eb53c7a722a5d9e676eb5f6b1800b7d740ef46a4db440f5a13a3ed')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Espectacles públics.', false), ('B', 'Activitats extraordinàries.', false), ('C', 'Activitats recreatives.', true), ('D', 'Activitats de restauració.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-local');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 3.1.a) de la Llei 11/2009, què caracteritza les activitats d''espectacles públics?', 'L''article 3.1.a) de la Llei 11/2009 defineix els espectacles públics per la contemplació, per part del públic, d''una representació o actuació feta per executants.', 'plcat_t21_espectacles_publics', (select id from public.topics where slug = 'plcat-t21-espectacles-publics'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856'), 'Art. 3 Llei 11/2009', 'y que congregan a un público que acude a las mismas para contemplarlas.', null, '165268690719dcee0aadd2178b108229b61ae1e55a95ed3ffcca6040925b5c43', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '165268690719dcee0aadd2178b108229b61ae1e55a95ed3ffcca6040925b5c43')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Consisteixen en activitats musicals per participar-hi o consumir.', false), ('B', 'Consisteixen en representacions, actuacions, exhibicions o projeccions fetes per actors, artistes o altres executants, que congreguen un públic que hi acudeix per contemplar-les.', true), ('C', 'Són sempre activitats esportives professionals.', false), ('D', 'Són activitats sense públic, emeses per mitjans audiovisuals.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-local');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 9.2 de la Llei 11/2009, els establiments on es permet l''entrada de menors han de complir, especialment, la normativa relativa a:', 'L''article 9.2 de la Llei 11/2009 imposa el compliment de la normativa de protecció de menors: alcohol, tabac, drogues, màquines amb premi o d''atzar, integritat física, psíquica i moral i limitació d''horaris.', 'plcat_t21_espectacles_publics', (select id from public.topics where slug = 'plcat-t21-espectacles-publics'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856'), 'Art. 9 Llei 11/2009', 'especialmente la relativa a la prohibición de venta y suministro de bebidas alcohólicas', null, '042f9e8aad6b1fb06cc0edd29b9e2cb60cad5f71408e20448d51726eaa44c892', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '042f9e8aad6b1fb06cc0edd29b9e2cb60cad5f71408e20448d51726eaa44c892')
