with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 10 de la Llei 11/2009, l''exercici del dret d''admissió:', 'L''article 10 de la Llei 11/2009 prohibeix qualsevol discriminació en l''exercici del dret d''admissió, tant en l''accés com en la permanència i l''ús dels serveis.', 'plcat_t21_espectacles_publics', (select id from public.topics where slug = 'plcat-t21-espectacles-publics'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856'), 'Art. 10 Llei 11/2009', 'El ejercicio del derecho de admisión no puede conllevar, en ningún caso, discriminación por razón de nacimiento, raza, sexo, religión, opinión, discapacidad, orientación sexual, identidad de género o cualquier otra condición', null, '7c535d7ffa6530889dc3d485fd3f98e44ca8a7ec108e9815e7dcb26e8e7fc903', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7c535d7ffa6530889dc3d485fd3f98e44ca8a7ec108e9815e7dcb26e8e7fc903')
  returning id
), o as (
