  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Permet al titular denegar l''entrada sense donar-ne cap motiu.', false), ('B', 'Només és aplicable als menors d''edat.', false), ('C', 'No pot comportar en cap cas discriminació per raó de naixement, raça, sexe, religió, opinió, discapacitat, orientació sexual, identitat de gènere o qualsevol altra condició.', true), ('D', 'Ha de ser autoritzat prèviament per la policia local.', false)) as v(label, body, ok)
)
