with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 24.2 de la Llei 11/2009, el personal responsable del control d''accés i d''aforament dels establiments oberts al públic ha de:', 'L''article 24.2 de la Llei 11/2009 exigeix requisits professionals i d''idoneïtat, formació en un centre habilitat i superar les proves de la direcció general competent en espectacles.', 'plcat_t21_espectacles_publics', (select id from public.topics where slug = 'plcat-t21-espectacles-publics'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856'), 'Art. 24 Llei 11/2009', 'Este personal debe asistir a cursos de formación impartidos por un centro debidamente habilitado y superar las pruebas de selección que convoque la dirección general competente en materia de espectáculos públicos y actividades recreativas.', null, '2a209b17f2a289a53e8245a238c3e4477b44b891fae802dcc8e2568ee17338ed', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2a209b17f2a289a53e8245a238c3e4477b44b891fae802dcc8e2568ee17338ed')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ser vigilant de seguretat privada habilitat pel Ministeri de l''Interior.', false), ('B', 'Complir els requisits professionals i d''idoneïtat, assistir a cursos de formació en un centre habilitat i superar les proves que convoqui la direcció general competent.', true), ('C', 'Ser membre d''un cos de policia en segona activitat.', false), ('D', 'Tenir només la majoria d''edat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
