with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 44 de la Llei 11/2009, els membres dels cossos i forces de seguretat que fan inspeccions en matèria d''espectacles:', 'L''article 44 de la Llei 11/2009 obliga titulars i organitzadors a facilitar les inspeccions, atribueix caràcter d''agents de l''autoritat als inspectors i obliga a estendre acta.', 'plcat_t21_espectacles_publics', (select id from public.topics where slug = 'plcat-t21-espectacles-publics'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856'), 'Art. 44 Llei 11/2009', 'Pueden realizar inspecciones los miembros de cuerpos y fuerzas de seguridad u otros servicios de inspección, los cuales, en el ejercicio de sus funciones, tienen el carácter de agentes de la autoridad', null, 'a775b813837bd7f21c3e9aec92a62cb8517b9d29e70e0537583bdab22a12502b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a775b813837bd7f21c3e9aec92a62cb8517b9d29e70e0537583bdab22a12502b')
