  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 44.3 de la Llei 11/2009, com a resultat d''una inspecció, l''acta que estenen els agents:', 'L''article 44.3 de la Llei 11/2009 regula l''acta d''inspecció, en què els interessats poden fer constar la disconformitat i les observacions, i que s''ha de notificar.', 'plcat_t21_espectacles_publics', (select id from public.topics where slug = 'plcat-t21-espectacles-publics'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856'), 'Art. 44.3 Llei 11/2009', '3. Como resultado de la inspección, los agentes actuantes deben extender un acta, en la cual los interesados pueden hacer constar su disconformidad y observaciones.', null, '7dc62f6ec08d7695c4a080d53a37d61142dbebb00ae9a1cda984dee9b47af26e', false
