  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 47 de la Llei 11/2009, quina d''aquestes conductes dels titulars o organitzadors és una falta MOLT GREU?', 'Tolerar de manera evident el consum il·legal i generalitzat de drogues és falta molt greu (art. 47.b); les altres conductes són faltes greus (art. 48.b, e i h).', 'plcat_t21_espectacles_publics', (select id from public.topics where slug = 'plcat-t21-espectacles-publics'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856'), 'Art. 47 Llei 11/2009', 'b) Tolerar de manera evidente, los titulares, explotadores u organizadores de las actividades de espectáculos públicos y de las actividades recreativas, el consumo ilegal y generalizado de drogas tóxicas', null, 'bab9d3cdaf252dff1ae3e4dfbcd2de0efbfece5660340c63e28dae7e84d612c6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bab9d3cdaf252dff1ae3e4dfbcd2de0efbfece5660340c63e28dae7e84d612c6')
  returning id
