  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 62.a) de la Llei 11/2009, quan s''adopta una mesura provisional prèvia perquè hi ha indicis clars que un espectacle pot ser constitutiu de delicte, l''òrgan que l''acorda l''ha de comunicar a l''autoritat judicial dins de:', 'L''article 62.a) de la Llei 11/2009 obliga a comunicar la mesura a l''autoritat judicial dins de les quaranta-vuit hores següents.', 'plcat_t21_espectacles_publics', (select id from public.topics where slug = 'plcat-t21-espectacles-publics'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856'), 'Art. 62 Llei 11/2009', 'En tal caso, el órgano que acuerda la medida provisional debe comunicarlo a la autoridad judicial dentro de las cuarenta y ocho horas siguientes.', null, '3efbb5a2499ef39c6eb83d65f6f63bc7eeb4bd99d1b22613523dc01e7d9084af', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3efbb5a2499ef39c6eb83d65f6f63bc7eeb4bd99d1b22613523dc01e7d9084af')
  returning id
