with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 65.2 de la Llei 11/2009, si els agents adopten mesures provisionals immediates, han de comunicar-ho a l''òrgan competent dins de les quaranta-vuit hores següents. En quin termini l''ha de confirmar, modificar o revocar aquest òrgan?', 'L''article 65.2 de la Llei 11/2009 fixa quaranta-vuit hores per comunicar la mesura i cinc dies perquè l''òrgan competent la confirmi, modifiqui o revoqui; l''incompliment dels terminis en comporta l''aixecament.', 'plcat_t21_espectacles_publics', (select id from public.topics where slug = 'plcat-t21-espectacles-publics'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856'), 'Art. 65.2 Llei 11/2009', 'el cual debe confirmarlas, modificarlas o revocarlas en el plazo de cinco días, a contar desde el primer día hábil siguiente al de la comunicación.', null, 'b9261f955b1283e2a2c3b38d97bc81b0e088f48b0b1a491839459eb37af8e123', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b9261f955b1283e2a2c3b38d97bc81b0e088f48b0b1a491839459eb37af8e123')
  returning id
), o as (
