  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina d''aquestes mesures provisionals immediates poden adoptar els agents segons l''article 65.3 de la Llei 11/2009?', 'L''article 65.3 de la Llei 11/2009 permet als agents suspendre activitats i precintar, desallotjar establiments en cas de perill greu o adoptar altres mesures menys restrictives i proporcionades. Les sancions i la revocació són competència de l''òrgan sancionador.', 'plcat_t21_espectacles_publics', (select id from public.topics where slug = 'plcat-t21-espectacles-publics'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856'), 'Art. 65.3 Llei 11/2009', 'a) La suspensión inmediata de las actividades y el precinto de los establecimientos, de las instalaciones o de los instrumentos, en el caso de que puedan producirse graves problemas de seguridad.', null, '7cd24842c0c3a1126b832cde7250f6de7fb3adce4d33faa4197ec9c46622af41', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7cd24842c0c3a1126b832cde7250f6de7fb3adce4d33faa4197ec9c46622af41')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La revocació definitiva de la llicència.', false), ('B', 'La suspensió immediata de les activitats i el precinte dels establiments, de les instal·lacions o dels instruments, si es poden produir problemes greus de seguretat.', true), ('C', 'La imposició d''una multa de fins a 10.000 euros.', false), ('D', 'La inhabilitació del titular per sis mesos.', false)) as v(label, body, ok)
)
