with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi d''ètica de la Policia de Catalunya (Acord GOV/25/2015), quins són els tres principis que un policia no pot deixar de respectar en cap cas?', 'El capítol I del Codi defineix els principis com les bases que en cap cas un policia pot deixar de respectar i els concreta en tres.', 'plcat_t22_etica_policial', (select id from public.topics where slug = 'plcat-t22-etica-policial'), 1, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656'), 'Codi d''ètica, cap. I', 'Es concreten en tres: a. Garantir els drets i les llibertats de totes les persones, b. Actuar amb integritat, proporcionalitat, congruència i oportunitat, i c. Actuar amb absoluta neutralitat política i imparciali', null, '03a752fcbd86daf74ffaa096ef407e62f13c96c2421800271eb2c88f095f44cb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '03a752fcbd86daf74ffaa096ef407e62f13c96c2421800271eb2c88f095f44cb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Obediència, disciplina i jerarquia.', false), ('B', 'Garantir els drets i les llibertats de totes les persones; actuar amb integritat, proporcionalitat, congruència i oportunitat; i actuar amb absoluta neutralitat política i imparcialitat.', true), ('C', 'Eficàcia, eficiència i economia.', false), ('D', 'Proximitat, transparència i coratge.', false)) as v(label, body, ok)
)
