with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 2 de la Llei 17/2015, d''igualtat efectiva de dones i homes, hi ha representació paritària quan:', 'L''article 2.i defineix la representació paritària amb la forquilla 40-60% i afegeix que s''ha de tendir al 50% de cada sexe.', 'plcat_t23_igualtat_no_discriminacio', (select id from public.topics where slug = 'plcat-t23-igualtat-no-discriminacio'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676'), 'Art. 2.i Llei 17/2015', 'ningún sexo supera el 60% del conjunto de personas a que se refiere ni es inferior al 40%, y que debe tender a alcanzar el 50% de personas de cada sexo', null, 'f6a6d917c04b8600f26c811105b919eead972db79d3276d05582b0b9e9feba00', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f6a6d917c04b8600f26c811105b919eead972db79d3276d05582b0b9e9feba00')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cap sexe supera el 60% ni és inferior al 40% del conjunt de persones de què es tracti.', true), ('B', 'Cap sexe supera el 70% ni és inferior al 30%.', false), ('C', 'Hi ha exactament el mateix nombre de dones que d''homes.', false), ('D', 'Les dones representen com a mínim una tercera part del conjunt.', false)) as v(label, body, ok)
)
