with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 17/2015, la situació en què una persona és, ha estat o pot ser tractada, per raó de sexe, de manera menys favorable que una altra en una situació anàloga és:', 'L''article 2.k defineix la discriminació directa com el tracte menys favorable per raó de sexe o de circumstàncies directament relacionades amb la condició biològica.', 'plcat_t23_igualtat_no_discriminacio', (select id from public.topics where slug = 'plcat-t23-igualtat-no-discriminacio'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676'), 'Art. 2.k Llei 17/2015', 'Discriminación directa: la situación en que se encuentra una persona que es, ha sido o puede ser tratada, por razón de sexo o de circunstancias directamente relacionadas con su condición biológica, de un modo menos favorable que otra en una situación análoga.', null, '0614e20c1e7b1371e6dde0a7b582e28e40d2f19cf0e5d19e8c9c82069eeea4b4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0614e20c1e7b1371e6dde0a7b582e28e40d2f19cf0e5d19e8c9c82069eeea4b4')
  returning id
