with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un criteri aparentment neutre que pot causar un perjudici més gran a les persones d''un dels sexes, i que no es pot justificar amb criteris objectius aliens al gènere, constitueix, segons la Llei 17/2015:', 'L''article 2.l defineix la discriminació indirecta a partir d''una disposició, criteri, interpretació o pràctica suposadament neutres; no ho és si és adequada, necessària i justificable objectivament.', 'plcat_t23_igualtat_no_discriminacio', (select id from public.topics where slug = 'plcat-t23-igualtat-no-discriminacio'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676'), 'Art. 2.l Llei 17/2015', 'Discriminación indirecta: la situación discriminatoria creada por una disposición, criterio, interpretación o práctica supuestamente neutros que pueden causar un perjuicio mayor a las personas de uno de los sexos', null, 'd77865f5ca7943f7979bfe356b1147787e68d0133c4d360c6abf79ffc64b67bc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd77865f5ca7943f7979bfe356b1147787e68d0133c4d360c6abf79ffc64b67bc')
  returning id
), o as (
