  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Discriminació directa.', false), ('B', 'Acció positiva.', false), ('C', 'Discriminació indirecta.', true), ('D', 'Discriminació per error.', false)) as v(label, body, ok)
)
