insert into public.topics (slug, title) values ('plcat-t02-constitucio-organitzacio-territorial', 'Tema 2. La Constitució espanyola: organització territorial, administració local i forces i cossos de seguretat') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t02-constitucio-organitzacio-territorial' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Administració pública i forces i cossos de seguretat (arts. 103 i 104)"},{"n":"2","title":"Control judicial de l''Administració i policia judicial (arts. 106 i 126)"},{"n":"3","title":"Estats d''alarma, excepció i setge (art. 116)"},{"n":"4","title":"Ministeri Fiscal (art. 124)"},{"n":"5","title":"Organització territorial: municipis, províncies i comunitats (arts. 137, 140 i 141)"},{"n":"6","title":"Hisendes locals (art. 142)"},{"n":"7","title":"Competències de les comunitats autònomes i de l''Estat en seguretat (arts. 148.1.22 i 149.1.29)"},{"n":"8","title":"Control de les comunitats autònomes (arts. 153 i 155)"}]'::jsonb, '["Art. 104 CE: «1. Las Fuerzas y Cuerpos de seguridad, bajo la dependencia del Gobierno, tendrán como misión proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana.»","Art. 104.2 CE: «2. Una ley orgánica determinará las funciones, principios básicos de actuación y estatutos de las Fuerzas y Cuerpos de seguridad.»","Art. 126 CE: «La policía judicial depende de los Jueces, de los Tribunales y del Ministerio Fiscal en sus funciones de averiguación del delito y descubrimiento y aseguramiento del delincuente»","Art. 103.1 CE: «actúa de acuerdo con los principios de eficacia, jerarquía, descentralización, desconcentración y coordinación, con sometimiento pleno a la ley y al Derecho.»","Art. 103.3 CE: «el acceso a la función pública de acuerdo con los principios de mérito y capacidad»","Art. 106.2 CE: «salvo en los casos de fuerza mayor, siempre que la lesión sea consecuencia del funcionamiento de los servicios públicos.»","Art. 116.2 CE: «2. El estado de alarma será declarado por el Gobierno mediante decreto acordado en Consejo de Ministros por un plazo máximo de quince días, dando cuenta al Congreso de los Diputados»","Art. 116.3 CE: «su duración, que no podrá exceder de treinta días, prorrogables por otro plazo igual, con los mismos requisitos.»","Art. 124 CE: «conforme a los principios de unidad de actuación y dependencia jerárquica y con sujeción, en todo caso, a los de legalidad e imparcialidad.»","Art. 137 CE: «El Estado se organiza territorialmente en municipios, en provincias y en las Comunidades Autónomas que se constituyan.»","Art. 140 CE: «Los Concejales serán elegidos por los vecinos del municipio mediante sufragio universal, igual, libre, directo y secreto, en la forma establecida por la ley.»","Art. 141 CE: «Cualquier alteración de los límites provinciales habrá de ser aprobada por las Cortes Generales mediante ley orgánica.»","Art. 142 CE: «se nutrirán fundamentalmente de tributos propios y de participación en los del Estado y de las Comunidades Autónomas.»","Art. 145 CE: «1. En ningún caso se admitirá la federación de Comunidades Autónomas.»","Art. 148.1.22 CE: «22.ª La vigilancia y protección de sus edificios e instalaciones. La coordinación y demás facultades en relación con las policías locales en los términos que establezca una ley orgánica.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229', null, null, null, null
  from public.topics t where t.slug = 'plcat-t02-constitucio-organitzacio-territorial'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
