insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 6/2006, de 19 de julio, de reforma del Estatuto de Autonomía de Cataluña (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t03-estatut-autonomia', 'Tema 3. L''Estatut d''autonomia de Catalunya: drets, deures i principis rectors, govern local i seguretat pública') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t03-estatut-autonomia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Catalunya com a nacionalitat i l''autogovern (arts. 1 i 2)"},{"n":"2","title":"Llengua pròpia i símbols (arts. 6 i 8)"},{"n":"3","title":"Drets de les persones i drets lingüístics (arts. 15, 32 i 33)"},{"n":"4","title":"Govern local: municipi, organització i competències (arts. 83, 84 i 86)"},{"n":"5","title":"Ordenació territorial (art. 91)"},{"n":"6","title":"Competències en règim local i seguretat pública (arts. 160 i 164)"}]'::jsonb, '["Art. 1 EAC: «Cataluña, como nacionalidad, ejerce su autogobierno constituida en Comunidad Autónoma de acuerdo con la Constitución y con el presente Estatuto, que es su norma institucional básica.»","Art. 2.2 EAC: «2. La Generalitat está integrada por el Parlamento, la Presidencia de la Generalitat, el Gobierno y las demás instituciones que establece el Capítulo V, del Título II.»","Art. 2.3 EAC: «también integran el sistema institucional de la Generalitat, como entes en los que ésta se organiza territorialmente, sin perjuicio de su autonomía.»","Art. 6.2 EAC: «Todas las personas tienen derecho a utilizar las dos lenguas oficiales y los ciudadanos de Cataluña el derecho y el deber de conocerlas.»","Art. 8 EAC: «3. La fiesta de Cataluña es el Día Once de Septiembre.»","Art. 8.2 EAC: «2. La bandera de Cataluña es la tradicional de cuatro barras rojas en fondo amarillo y debe estar presente en los edificios públicos y en los actos oficiales que tengan lugar en Cataluña.»","Art. 15.2 EAC: «2. Todas las personas tienen derecho a vivir con dignidad, seguridad y autonomía, libres de explotación, de malos tratos y de todo tipo de discriminación»","Art. 32 EAC: «Los actos jurídicos realizados en cualquiera de las dos lenguas oficiales tienen, en cuanto a la lengua, plena validez y eficacia.»","Art. 33.1 EAC: «En las relaciones con las instituciones, las organizaciones y las Administraciones públicas en Cataluña, todas las personas tienen derecho a utilizar la lengua oficial que elijan.»","Art. 50.5 EAC: «También deben utilizarlo en las comunicaciones y las notificaciones dirigidas a personas físicas o jurídicas residentes en Cataluña, sin perjuicio del derecho de los ciudadanos a recibirlas en castellano si lo piden.»","Art. 83 EAC: «1. Cataluña estructura su organización territorial básica en municipios y veguerías.»","Art. 84.2.e EAC: «e) La regulación de las condiciones de seguridad en las actividades organizadas en espacios públicos y en los locales de concurrencia pública. La coordinación mediante la Junta de Seguridad de los distintos cuerpos y fuerzas presentes en el municipio.»","Art. 86.1 EAC: «1. El municipio es el ente local básico de la organización territorial de Cataluña y el medio esencial de participación de la comunidad local en los asuntos públicos.»","Art. 86.4 EAC: «4. Los actos y acuerdos adoptados por los municipios no pueden ser objeto de control de oportunidad por ninguna otra administración.»","Art. 91.3 EAC: «3. Los Consejos de veguería sustituyen a las Diputaciones.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087', null, null, null, null
  from public.topics t where t.slug = 'plcat-t03-estatut-autonomia'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
