insert into public.topics (slug, title) values ('plcat-t04-regim-local', 'Tema 4. Règim local: el municipi, l''organització municipal i les ordenances (Llei 7/1985)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t04-regim-local' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Entitats locals i municipi (arts. 3 i 11)"},{"n":"2","title":"Territori, població i padró (arts. 12 i 15)"},{"n":"3","title":"Organització municipal: òrgans necessaris (art. 20)"},{"n":"4","title":"L''alcalde i les seves atribucions, també en policia (art. 21)"},{"n":"5","title":"El Ple i la Junta de Govern Local (arts. 22 i 23)"},{"n":"6","title":"Competències pròpies i serveis mínims (arts. 25 i 26)"},{"n":"7","title":"Ordenances: procediment d''aprovació (art. 49)"},{"n":"8","title":"Infraccions i sancions de les ordenances (arts. 139-141)"}]'::jsonb, '["Art. 3 LBRL: «1. Son Entidades Locales territoriales: a) El Municipio. b) La Provincia. c) La Isla en los archipiélagos balear y canario.»","Art. 11.2 LBRL: «2. Son elementos del Municipio el territorio, la población y la organización.»","Art. 12 LBRL: «1. El término municipal es el territorio en que el ayuntamiento ejerce sus competencias. 2. Cada municipio pertenecerá a una sola provincia.»","Art. 15 LBRL: «Quien viva en varios municipios deberá inscribirse únicamente en el que habite durante más tiempo al año.»","Art. 20 LBRL: «a) El Alcalde, los Tenientes de Alcalde y el Pleno existen en todos los ayuntamientos.»","Art. 21.1.i LBRL: «i) Ejercer la jefatura de la Policía Municipal.»","Art. 21.3 LBRL: «3. El Alcalde puede delegar el ejercicio de sus atribuciones, salvo las de convocar y presidir las sesiones del Pleno y de la Junta de Gobierno Local»","Art. 21.1.m LBRL: «m) Adoptar personalmente, y bajo su responsabilidad, en caso de catástrofe o de infortunios públicos o grave riesgo de los mismos, las medidas necesarias y adecuadas dando cuenta inmediata al Pleno.»","Art. 21.1.e LBRL: «e) Dictar bandos.»","Art. 22.2.d LBRL: «d) La aprobación del reglamento orgánico y de las ordenanzas.»","Art. 23 LBRL: «1. La Junta de Gobierno Local se integra por el Alcalde y un número de Concejales no superior al tercio del número legal de los mismos, nombrados y separados libremente por aquél, dando cuenta al Pleno.»","Art. 23.3 LBRL: «3. Los Tenientes de Alcalde sustituyen, por el orden de su nombramiento y en los casos de vacante, ausencia o enfermedad, al Alcalde»","Art. 25.2.f LBRL: «f) Policía local, protección civil, prevención y extinción de incendios.»","Art. 26.1 LBRL: «c) En los Municipios con población superior a 20.000 habitantes, además: protección civil»","Art. 26.1.d LBRL: «d) En los Municipios con población superior a 50.000 habitantes, además: transporte colectivo urbano de viajeros y medio ambiente urbano.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392', null, null, null, null
  from public.topics t where t.slug = 'plcat-t04-regim-local'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
