insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t05-procediment-administratiu', 'Tema 5. El procediment administratiu comú: interessats, activitat de les administracions i actes (Llei 39/2015)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t05-procediment-administratiu' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Interessats i capacitat d''obrar (art. 4)"},{"n":"2","title":"Relació electrònica amb l''Administració (art. 14)"},{"n":"3","title":"Obligació de resoldre i silenci administratiu (arts. 21 i 24)"},{"n":"4","title":"Còmput de terminis (art. 30)"},{"n":"5","title":"Eficàcia i validesa dels actes: nul·litat i anul·labilitat (arts. 39, 47 i 48)"},{"n":"6","title":"Drets de l''interessat en el procediment (art. 53)"},{"n":"7","title":"Esmena de la sol·licitud i terminació (arts. 68 i 85)"},{"n":"8","title":"Recursos administratius: alçada i reposició (arts. 112, 122 i 124)"}]'::jsonb, '["Art. 4 Llei 39/2015: «a) Quienes lo promuevan como titulares de derechos o intereses legítimos individuales o colectivos.»","Art. 14.1 Llei 39/2015: «1. Las personas físicas podrán elegir en todo momento si se comunican con las Administraciones Públicas para el ejercicio de sus derechos y obligaciones a través de medios electrónicos o no»","Art. 14.2 Llei 39/2015: «a) Las personas jurídicas.»","Art. 21.1 Llei 39/2015: «1. La Administración está obligada a dictar resolución expresa y a notificarla en todos los procedimientos cualquiera que sea su forma de iniciación.»","Art. 21.3 Llei 39/2015: «3. Cuando las normas reguladoras de los procedimientos no fijen el plazo máximo, éste será de tres meses.»","Art. 21.2 Llei 39/2015: «Este plazo no podrá exceder de seis meses salvo que una norma con rango de Ley establezca uno mayor»","Art. 24.1 Llei 39/2015: «legitima al interesado o interesados para entenderla estimada por silencio administrativo»","Art. 30.2 Llei 39/2015: «cuando los plazos se señalen por días, se entiende que éstos son hábiles, excluyéndose del cómputo los sábados, los domingos y los declarados festivos.»","Art. 30.1 Llei 39/2015: «no podrán tener una duración superior a veinticuatro horas, en cuyo caso se expresarán en días.»","Art. 39.1 Llei 39/2015: «1. Los actos de las Administraciones Públicas sujetos al Derecho Administrativo se presumirán válidos y producirán efectos desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa.»","Art. 47 Llei 39/2015: «b) Los dictados por órgano manifiestamente incompetente por razón de la materia o del territorio.»","Art. 48 Llei 39/2015: «1. Son anulables los actos de la Administración que incurran en cualquier infracción del ordenamiento jurídico, incluso la desviación de poder.»","Art. 53 Llei 39/2015: «a) A conocer, en cualquier momento, el estado de la tramitación de los procedimientos en los que tengan la condición de interesados»","Art. 68 Llei 39/2015: «se requerirá al interesado para que, en un plazo de diez días, subsane la falta o acompañe los documentos preceptivos, con indicación de que, si así no lo hiciera, se le tendrá por desistido de su petición»","Art. 85.3 Llei 39/2015: «el órgano competente para resolver el procedimiento aplicará reducciones de, al menos, el 20 % sobre el importe de la sanción propuesta, siendo éstos acumulables entre sí.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565', null, null, null, null
  from public.topics t where t.slug = 'plcat-t05-procediment-administratiu'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
