insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 2/1986, de 13 de marzo, de Fuerzas y Cuerpos de Seguridad (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t06-forces-cossos-seguretat', 'Tema 6. La Llei orgànica 2/1986 de forces i cossos de seguretat: principis bàsics d''actuació i policies locals') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t06-forces-cossos-seguretat' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Forces i cossos de seguretat i competència de l''Estat (arts. 1 i 2)"},{"n":"2","title":"Principis bàsics d''actuació (art. 5)"},{"n":"3","title":"Formació, retribució i règim disciplinari (arts. 6, 7 i 8)"},{"n":"4","title":"Forces i cossos de seguretat de l''Estat (arts. 9 i 11)"},{"n":"5","title":"Policia judicial (art. 29)"},{"n":"6","title":"Policies locals: naturalesa i funcions (arts. 51 i 53)"},{"n":"7","title":"Juntes locals de seguretat (art. 54)"}]'::jsonb, '["Art. 1 LO 2/1986: «1. La Seguridad Pública es competencia exclusiva del Estado. Su mantenimiento corresponde al Gobierno de la Nación.»","Art. 1.3 LO 2/1986: «3. Las Corporaciones Locales participarán en el mantenimiento de la seguridad pública en los términos establecidos en la Ley Reguladora de las Bases de Régimen Local y en el marco de esta Ley.»","Art. 2 LO 2/1986: «Son Fuerzas y Cuerpos de Seguridad: a) Las Fuerzas y Cuerpos de Seguridad del Estado dependientes del Gobierno de la Nación. b) Los Cuerpos de Policía dependientes de las Comunidades Autónomas. c) Los Cuerpos de Policía dependientes de las Corporaciones Locales.»","Art. 5.1 LO 2/1986: «b) Actuar, en el cumplimiento de sus funciones, con absoluta neutralidad política e imparcialidad y, en consecuencia, sin discriminación alguna por razón de raza, religión u opinión.»","Art. 5.2.c LO 2/1986: «rigiéndose al hacerlo por los principios de congruencia, oportunidad y proporcionalidad en la utilización de los medios a su alcance.»","Art. 5.3 LO 2/1986: «a) Los miembros de las Fuerzas y Cuerpos de Seguridad deberán identificarse debidamente como tales en el momento de efectuar una detención.»","Art. 5.4 LO 2/1986: «Deberán llevar a cabo sus funciones con total dedicación, debiendo intervenir siempre, en cualquier tiempo y lugar, se hallaren o no de servicio, en defensa de la Ley y de la seguridad ciudadana.»","Art. 5.5 LO 2/1986: «No estarán obligados a revelar las fuentes de información salvo que el ejercicio de sus funciones o las disposiciones de la Ley les impongan actuar de otra manera.»","Art. 5.6 LO 2/1986: «Son responsables personal y directamente por los actos que en su actuación profesional llevaren a cabo»","Art. 6.3 LO 2/1986: «3. Los miembros de las Fuerzas y Cuerpos de Seguridad deberán jurar o prometer acatamiento a la Constitución como norma fundamental del Estado.»","Art. 7 LO 2/1986: «tendrán al efecto de su protección penal la consideración de autoridad.»","Art. 8 LO 2/1986: «1. La jurisdicción ordinaria será la competente para conocer de los delitos que se cometan contra miembros de las Fuerzas y Cuerpos de Seguridad, así como de los cometidos por éstos en el ejercicio de sus funciones.»","Art. 9 LO 2/1986: «b) La Guardia Civil, que es un Instituto Armado de naturaleza militar»","Art. 11.2 LO 2/1986: «a) Corresponde al Cuerpo Nacional de Policía ejercitar dichas funciones en las capitales de provincia y en los términos municipales y núcleos urbanos que el Gobierno determine.»","Art. 29.2 LO 2/1986: «tendrán carácter colaborador de las Fuerzas y Cuerpos de Seguridad del Estado el personal de Policía de las Comunidades Autónomas y de las Corporaciones Locales.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859', null, null, null, null
  from public.topics t where t.slug = 'plcat-t06-forces-cossos-seguretat'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
