insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 16/1991, de 10 de julio, de las Policías Locales (Cataluña) (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t07-policies-locals-funcions', 'Tema 7. La Llei 16/1991 de les policies locals: naturalesa, funcions, coordinació, estructura i accés') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t07-policies-locals-funcions' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Naturalesa i àmbit de les policies locals (arts. 1-3)"},{"n":"2","title":"Denominació, uniformitat i armes"},{"n":"3","title":"Funcions de les policies locals"},{"n":"4","title":"Vigilants municipals"},{"n":"5","title":"Coordinació: Comissió de Coordinació de les Policies Locals"},{"n":"6","title":"Estructura i escala de comandament"},{"n":"7","title":"Accés i formació a l''Institut de Seguretat Pública (arts. 24, 26 i 29)"}]'::jsonb, '["Art. 2.1 Llei 16/1991: «1. Las Policías locales son institutos armados de naturaleza civil con estructura y organización jerarquizadas.»","Art. 2.3 Llei 16/1991: «pueden recibir también la denominación específica de Policía municipal o de Guardia urbana.»","Art. 3 Llei 16/1991: «2. En los Municipios de menos de 10.000 habitantes puede existir Policía local si acuerda su creación la mayoría absoluta del número legal de miembros de la correspondiente Corporación local y lo autoriza el Consejero de Gobernación, previo informe de la Comisión de Coordinación de las Policías Locales.»","Art. 1.3 Llei 16/1991: «3. El servicio que compete a las Policías locales será prestado directamente por las respectivas Corporaciones locales, que no pueden constituir órganos especiales de gestión ni aprobar la concesión, el arrendamiento ni ninguna otra forma de gestión indirecta del servicio.»","Art. 4 Llei 16/1991: «2. El mando de la Policía local es ejercido por el Alcalde, que puede delegar las correspondientes atribuciones, de acuerdo con la normativa vigente.»","Art. 5 Llei 16/1991: «2. Las Policías locales solamente pueden actuar fuera de su ámbito territorial en situaciones de emergencia y previa autorización de las autoridades competentes. Se dará cuenta de estas actuaciones al Departamento de Gobernación.»","Art. 6 Llei 16/1991: «Antes de tomar posesión del cargo, los Policías locales jurarán o prometerán acatar la Constitución, como norma fundamental del Estado, y respetar y observar el Estatuto de Autonomía, como norma institucional básica de Cataluña.»","Art. 7 Llei 16/1991: «No se consideran agentes de la autoridad, en ningún caso, los vigilantes, alguaciles o similares que actúan de manera complementaria o auxiliar a una policía local municipal existente.»","Art. 8 Llei 16/1991: «2. El Alcalde determinará, de forma motivada, las circunstancias y los servicios en que no se llevarán armas de fuego.»","Art. 10 Llei 16/1991: «d) Utilizar las armas solamente en las situaciones en que exista un riesgo racionalmente grave para su vida o su integridad física o las de terceras personas y en aquellas circunstancias que puedan suponer un grave riesgo para la seguridad ciudadana»","Art. 11 Llei 16/1991: «b) Ordenar, señalizar y dirigir el tráfico en el núcleo urbano, de acuerdo con lo establecido en las normas de circulación.»","Art. 11.c Llei 16/1991: «c) Instruir atestados por accidentes de circulación acaecidos dentro del núcleo urbano, en cuyo caso comunicarán las actuaciones realizadas a las Fuerzas o Cuerpos de Seguridad competentes.»","Art. 11.g-h Llei 16/1991: «h) Cooperar en la resolución de los conflictos privados, cuando sean requeridas para ello.»","Art. 12 Llei 16/1991: «b) Practicar, por iniciativa propia o a requerimiento de la autoridad judicial, del Ministerio Fiscal o de los superiores jerárquicos las primeras diligencias de prevención y custodia de detenidos»","Art. 13 Llei 16/1991: «Los Vigilantes a que se refiere el artículo 1.2 pueden realizar únicamente las actuaciones siguientes:»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343', null, null, null, null
  from public.topics t where t.slug = 'plcat-t07-policies-locals-funcions'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
