insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 16/1991, de 10 de julio, de las Policías Locales (Cataluña) (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t08-policies-locals-estatut-disciplina', 'Tema 8. La Llei 16/1991 de les policies locals: drets i deures, situacions i règim disciplinari') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t08-policies-locals-estatut-disciplina' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Drets dels policies locals"},{"n":"2","title":"Deures i incompatibilitats"},{"n":"3","title":"Situacions administratives"},{"n":"4","title":"Règim disciplinari: faltes molt greus, greus i lleus"},{"n":"5","title":"Sancions i prescripció"},{"n":"6","title":"Procediment i suspensió provisional"}]'::jsonb, '["Art. 38 Llei 16/1991: «Los Policías locales no pueden ejercer el derecho de huelga ni participar en acciones sustitutivas de éste o en actuaciones concertadas con la finalidad de alterar el funcionamiento normal de los servicios.»","Art. 35 Llei 16/1991: «3. Corresponde al Pleno de la respectiva Corporación Local la fijación de las retribuciones complementarias»","Art. 37 Llei 16/1991: «La condición de Policía local es incompatible con el ejercicio de ninguna otra actividad pública o privada, excepción hecha de las actividades no incluidas en la legislación reguladora de las incompatibilidades.»","Art. 41 Llei 16/1991: «Las Corporaciones Locales garantizarán la necesaria defensa jurídica a sus Policías locales en las causas judiciales que se sigan contra ellos a consecuencia de actuaciones realizadas en el ejercicio de sus funciones.»","Art. 42 Llei 16/1991: «2. Los miembros de la Policía local dispondrán de una revisión médica anual.»","Art. 43 Llei 16/1991: «por razón de edad, que en ningún caso será inferior a cincuenta y siete años»","Art. 43.3 Llei 16/1991: «3. El paso a la situación de segunda actividad no representará una disminución de las retribuciones básicas ni del grado personal de los afectados.»","Art. 44 Llei 16/1991: «se compondrá de tres Médicos, uno designado por el Ayuntamiento, uno designado por el interesado y uno escogido por sorteo entre los facultativos del Servicio Catalán de la Salud»","Art. 47 Llei 16/1991: «Las faltas cometidas por los Policías locales en el ejercicio de sus funciones pueden ser muy graves, graves y leves.»","Art. 48 Llei 16/1991: «g) El abandono del servicio.»","Art. 48-49 Llei 16/1991: «n) La pérdida de las armas, así como permitir su sustracción por negligencia simple.»","Art. 49 Llei 16/1991: «m) La reincidencia en la comisión de faltas leves.»","Art. 50 Llei 16/1991: «c) El descuido en la presentación personal.»","Art. 51 Llei 16/1991: «2. Los Policías locales que encubren las faltas muy graves y graves consumadas incurren en una falta de un grado inferior.»","Art. 52 Llei 16/1991: «a) La suspensión de funciones, por más de quince días y menos de un año, con pérdida de las retribuciones.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343', null, null, null, null
