insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 4/2003, de 7 de abril, de Ordenación del Sistema de Seguridad Pública de Cataluña (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t09-sistema-seguretat-catalunya', 'Tema 9. La Llei 4/2003 d''ordenació del sistema de seguretat pública de Catalunya i l''Institut de Seguretat Pública') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t09-sistema-seguretat-catalunya' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Sistema de seguretat pública de Catalunya: objecte i principis (Llei 4/2003)"},{"n":"2","title":"Competències de la Generalitat i dels municipis"},{"n":"3","title":"Juntes locals de seguretat i plans de seguretat"},{"n":"4","title":"Institut de Seguretat Pública de Catalunya: naturalesa i funcions (Llei 10/2007)"},{"n":"5","title":"Formació bàsica i promoció a l''ISPC"}]'::jsonb, '["Art. 3.1 Llei 4/2003: «a) Las autoridades de seguridad. b) Los cuerpos policiales y demás servicios, públicos o privados, de seguridad. c) Los órganos de coordinación y participación en materia de seguridad.»","Art. 2 Llei 4/2003: «c) Proximidad a los ciudadanos y descentralización de los servicios públicos.»","Art. 4.1 Llei 4/2003: «En el ámbito local, los alcaldes son también autoridades superiores en materia de seguridad, en el marco de sus competencias.»","Art. 5.1 Llei 4/2003: «1. La Policía de la Generalidad-Mossos d''Esquadra y las policías de los ayuntamientos, con la denominación de policía local, policía municipal, guardia urbana o cualquier otra denominación tradicional, constituyen la policía de las instituciones propias de Cataluña.»","Art. 5.4 Llei 4/2003: «en particular, por los de complementariedad, coordinación, colaboración, cooperación y auxilio mutuo, especialmente en el seno de las juntas locales de seguridad.»","Art. 6 Llei 4/2003: «1. El Consejo de Seguridad de Cataluña es el órgano consultivo y de participación superior en Cataluña en materia de seguridad»","Art. 3.3 Llei 4/2003: «3. La Junta de Seguridad de Cataluña es el órgano superior de coordinación entre la Policía de la Generalidad y las fuerzas y cuerpos de seguridad del Estado»","Art. 8 Llei 4/2003: «a) El consejero o consejera del departamento con competencias en materia de seguridad pública, que la preside. b) Cinco vocales en representación de los ayuntamientos. c) Cinco vocales en representación del Gobierno.»","Art. 9.1 Llei 4/2003: «1. En los municipios que tengan policía local debe existir una junta local de seguridad»","Art. 9.2 Llei 4/2003: «2. La junta local de seguridad está integrada por el alcalde o la alcalde, que la preside, con voz y voto»","Art. 10 Llei 4/2003: «b) Elaborar y aprobar el plan de seguridad local y los planes de actuación específicos que sean procedentes en el ámbito respectivo»","Art. 11 Llei 4/2003: «1. Las juntas locales de seguridad deben crear una mesa de coordinación operativa, como órgano permanente y estable de coordinación y cooperación de los diversos cuerpos y servicios de seguridad en el municipio.»","Art. 1 Llei 10/2007: «1. Se crea el Instituto de Seguridad Pública de Cataluña como entidad autónoma de carácter administrativo adscrita al departamento competente en materia de seguridad pública.»","Art. 7 Llei 10/2007: «1. El presidente o presidenta del Instituto de Seguridad Pública de Cataluña es el consejero o consejera del departamento competente en materia de seguridad pública.»","Art. 3.3 Llei 10/2007: «a) Los miembros de los cuerpos de policía de Cataluña, los vigilantes y auxiliares de la policía local»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620', null, null, null, 'Otras normas citadas: Llei 10/2007 (https://www.boe.es/buscar/act.php?id=BOE-A-2007-15546)'
  from public.topics t where t.slug = 'plcat-t09-sistema-seguretat-catalunya'
