insert into public.sources (title, url, kind, publisher, published_on) values ('Decret 219/1996, de 12 de juny, pel qual s''aprova el Reglament d''armament de les policies locals (text consolidat)', 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=129214', 'diario_autonomico'::public.source_kind, 'Generalitat de Catalunya · Portal Jurídic de Catalunya', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t10-armament', 'Tema 10. La policia local com a cos armat: Reglament d''armament de les policies locals i Reglament d''armes') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t10-armament' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Reglament d''armament de les policies locals (Decret 219/1996)"},{"n":"2","title":"Arma reglamentària i dotació"},{"n":"3","title":"Custòdia, dipòsit i revisió"},{"n":"4","title":"Reglament d''armes: classificació (art. 3)"},{"n":"5","title":"Llicències i guies de pertinença del personal policial (arts. 114 i 115)"}]'::jsonb, '["Art. 2 Decret 219/1996: «2.2 Tant les armes de foc com la seva munició són propietat dels ajuntaments respectius.»","Art. 2.1 Decret 219/1996: «2.1 Tots els membres dels cossos de policia local de Catalunya hauran de ser dotats d''una arma reglamentària de foc curta per a l''exercici de les seves funcions»","Art. 3 Decret 219/1996: «3.1 Correspon a l''alcalde l''adjudicació de l''arma de foc als funcionaris de carrera nomenats policies locals»","Art. 4 Decret 219/1996: «L''arma de foc es durà sempre que s''estigui de servei.»","Art. 5 Decret 219/1996: «Queda prohibida la tinença d''armes de foc als vigilants, al personal interí dels cossos de policia local sempre que no sigui funcionari o funcionària de carrera de qualsevol cos policial»","Art. 10 Decret 219/1996: «L''alcalde, quan així ho aconsellin circumstàncies especials, podrà concedir als membres de la seva policia local autorització excepcional per a la possessió d''una segona arma de foc curta»","Art. 12 Decret 219/1996: «el titular de la guia ho comunicarà al comandament corresponent, i s''abstindrà de manipular o d''efectuar gestions particulars per reparar-ne les deficiències.»","Art. 14 Decret 219/1996: «El cap del cos comunicarà de forma immediata a la Intervenció d''Armes de la Guàrdia Civil les pèrdues o sostraccions de qualsevol arma de foc o guia de pertinença»","Art. 13.2 Decret 219/1996: «13.2 En cas de pèrdua o sostracció de la guia de pertinença, caldrà entregar l''arma corresponent al cap del cos o al comandament delegat»","Art. 16 Decret 219/1996: «a) En deixar el servei actiu.»","Art. 17 Decret 219/1996: «l''alcalde o persona en qui delegui ordenarà la retirada de l''arma de foc, per un període no superior a quinze dies.»","Art. 19 Decret 219/1996: «on cada agent, en acabar el servei, dipositarà l''arma reglamentària, llevat d''autorització expressa en contrari de l''alcalde o persona en qui delegui.»","Art. 3 Reglament d''armes: «Armas de fuego cortas: Comprende las pistolas y revólveres.»","Art. 114 Reglament d''armes: «d) Los miembros de los Cuerpos de Policía de las Comunidades Autónomas y de las Corporaciones locales.»","Art. 115 Reglament d''armes: «h) Para el personal de los Cuerpos de Policía de las Entidades locales, con las letras PL, el número correspondiente a cada Entidad local en el Código Geográfico Nacional y numeración correlativa de las guías.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=129214'), 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=129214', null, null, null, 'Otras normas citadas: Reglament d''armes (https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202)'
  from public.topics t where t.slug = 'plcat-t10-armament'
