insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto de 14 de septiembre de 1882, Ley de Enjuiciamiento Criminal (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t13-policia-judicial-detencio', 'Tema 13. La Llei d''enjudiciament criminal: policia judicial, detenció i drets de la persona detinguda') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t13-policia-judicial-detencio' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Policia judicial: funcions (art. 282)"},{"n":"2","title":"Atestat i diligències (arts. 284, 292 i 295)"},{"n":"3","title":"Valor de l''atestat (art. 297)"},{"n":"4","title":"La detenció: supòsits i obligats a detenir (arts. 489-493)"},{"n":"5","title":"Forma de practicar la detenció i terminis (arts. 494-496)"},{"n":"6","title":"Drets de la persona detinguda (art. 520)"}]'::jsonb, '["Art. 282 LECrim: «averiguar los delitos públicos que se cometieren en su territorio o demarcación; practicar, según sus atribuciones, las diligencias necesarias para comprobarlos y descubrir a los delincuentes»","Art. 284.2 LECrim: «a) Que se trate de delitos contra la vida, contra la integridad física, contra la libertad e indemnidad sexuales o de delitos relacionados con la corrupción;»","Art. 292 LECrim: «en el cual especificarán con la mayor exactitud los hechos por ellos averiguados, insertando las declaraciones e informes recibidos y anotando todas las circunstancias que hubiesen observado y pudiesen ser prueba o indicio del delito.»","Art. 295 LECrim: «En ningún caso los funcionarios de Policía Judicial podrán dejar transcurrir más de veinticuatro horas sin dar conocimiento a la autoridad judicial o al Ministerio Fiscal de las diligencias que hubieran practicado»","Art. 297 LECrim: «se considerarán denuncias para los efectos legales.»","Art. 489 LECrim: «Ningún español ni extranjero podrá ser detenido sino en los casos y en la forma que las leyes prescriban.»","Art. 490 LECrim: «2.º Al delincuente in fraganti.»","Art. 492 LECrim: «1.ª Que la Autoridad o agente tenga motivos racionalmente bastantes para creer en la existencia de un hecho que presente los caracteres de delito. 2.ª Que los tenga también bastantes para creer que la persona a quien intente detener tuvo participación en él.»","Art. 495 LECrim: «No se podrá detener por la presunta comisión de delitos leves, a no ser que el presunto reo no tuviese domicilio conocido ni diese fianza bastante»","Art. 496 LECrim: «deberá ponerla en libertad o entregarla al Juez más próximo al lugar en que hubiere hecho la detención dentro de las veinticuatro horas siguientes al acto de la misma.»","Art. 520.1 LECrim: «1. La detención y la prisión provisional deberán practicarse en la forma que menos perjudique al detenido o preso en su persona, reputación y patrimonio.»","Art. 520.2 LECrim: «2. Toda persona detenida o presa será informada por escrito, en un lenguaje sencillo y accesible, en una lengua que comprenda y de forma inmediata»","Art. 520.2.e LECrim: «Los extranjeros tendrán derecho a que las circunstancias anteriores se comuniquen a la oficina consular de su país.»","Art. 520.4 LECrim: «4. Si se tratare de un menor, será puesto a disposición de las Secciones de Menores de la Fiscalía y se comunicará el hecho y el lugar de custodia a quienes ejerzan la patria potestad, la tutela o la guarda de hecho del mismo»","Art. 520.5 LECrim: «El abogado designado acudirá al centro de detención con la máxima premura, siempre dentro del plazo máximo de tres horas desde la recepción del encargo.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036', null, null, null, null
  from public.topics t where t.slug = 'plcat-t13-policia-judicial-detencio'
