insert into public.topics (slug, title) values ('plcat-t14-entrada-registre-habeas-corpus', 'Tema 14. Entrada i registre en lloc tancat i procediment d''habeas corpus') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t14-entrada-registre-habeas-corpus' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Entrada i registre en lloc tancat: concepte de domicili (arts. 545-554)"},{"n":"2","title":"Autorització judicial i consentiment"},{"n":"3","title":"Pràctica del registre i acta (arts. 566-569)"},{"n":"4","title":"Habeas corpus: objecte i persones il·legalment detingudes (LO 6/1984, arts. 1 i 2)"},{"n":"5","title":"Legitimació i iniciació (arts. 3 i 4)"},{"n":"6","title":"Tramitació i resolució (arts. 5-8)"}]'::jsonb, '["Art. 545 LECrim: «Nadie podrá entrar en el domicilio de un español o extranjero residente en España sin su consentimiento, excepto en los casos y en la forma expresamente previstos en las leyes.»","Art. 550 LECrim: «o a falta de consentimiento, en virtud de auto motivado, que se notificará a la persona interesada inmediatamente, o lo más tarde dentro de las veinticuatro horas de haberse dictado.»","Art. 553 LECrim: «cuando un delincuente, inmediatamente perseguido por los Agentes de la autoridad, se oculte o refugie en alguna casa»","Art. 554 LECrim: «3.º Los buques nacionales mercantes.»","Art. 554.4 LECrim: «el espacio físico que constituya el centro de dirección de las mismas, ya se trate de su domicilio social o de un establecimiento dependiente»","Art. 558 LECrim: «El auto de entrada y registro en el domicilio de un particular será siempre fundado, y el Juez expresará en él concretamente el edificio o lugar cerrado en que haya de verificarse, si tendrá lugar tan sólo de día y la Autoridad o funcionario que los haya de practicar.»","Art. 566 LECrim: «Si no se halla a nadie, se hará constar por diligencia, que se extenderá con asistencia de dos vecinos, los cuales deberán firmarla.»","Art. 569 LECrim: «El registro se practicará siempre en presencia del Secretario del Juzgado o Tribunal que lo hubiera autorizado, o del Secretario del servicio de guardia que le sustituya»","Art. 1 LO 6/1984: «se podrá obtener la inmediata puesta a disposición de la Autoridad judicial competente, de cualquier persona detenida ilegalmente.»","Art. 2 LO 6/1984: «Es competente para conocer la solicitud de «Habeas Corpus» el Juez de Instrucción del lugar en que se encuentre la persona privada de libertad»","Art. 3 LO 6/1984: «b) El Ministerio Fiscal. c) El Defensor del Pueblo. d) El abogado defensor del privado de libertad.»","Art. 4 LO 6/1984: «no siendo preceptiva la intervención de Abogado ni de Procurador.»","Art. 5 LO 6/1984: «La autoridad gubernativa, agente de la misma o funcionario público, estarán obligados a poner inmediatamente en conocimiento del Juez competente la solicitud de «Habeas Corpus»»","Art. 6 LO 6/1984: «Contra la resolución que en uno u otro caso se adopte, no cabrá recurso alguno.»","Art. 7 LO 6/1984: «En el plazo de veinticuatro horas, contadas desde que sea dictado el auto de incoación, los Jueces practicarán todas las actuaciones a que se refiere este artículo y dictarán la resolución que proceda.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036', null, null, null, 'Otras normas citadas: LO 6/1984 (https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620)'
  from public.topics t where t.slug = 'plcat-t14-entrada-registre-habeas-corpus'
on conflict (topic_id, locale) do update
