insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t18-menors', 'Tema 18. La Llei orgànica 5/2000 de responsabilitat penal dels menors: la detenció de menors') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t18-menors' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Àmbit d''aplicació de la LO 5/2000 i edat penal"},{"n":"2","title":"Drets dels menors i principis"},{"n":"3","title":"Detenció del menor: termini i custòdia"},{"n":"4","title":"Comunicació al Ministeri Fiscal i als representants legals"},{"n":"5","title":"Mesures aplicables"}]'::jsonb, '["Art. 1 LO 5/2000: «1. Esta Ley se aplicará para exigir la responsabilidad de las personas mayores de catorce años y menores de dieciocho»","Art. 3 LO 5/2000: «Cuando el autor de los hechos mencionados en los artículos anteriores sea menor de catorce años, no se le exigirá responsabilidad con arreglo a la presente Ley, sino que se le aplicará lo dispuesto en las normas sobre protección de menores»","Art. 2.3 LO 5/2000: «3. La competencia corresponde al Juez de Menores del lugar donde se haya cometido el hecho delictivo»","Art. 5.3 LO 5/2000: «3. Las edades indicadas en el articulado de esta Ley se han de entender siempre referidas al momento de la comisión de los hechos»","Art. 7.1 LO 5/2000: «a) Internamiento en régimen cerrado.»","Art. 7.1.g LO 5/2000: «g) Permanencia de fin de semana. Las personas sometidas a esta medida permanecerán en su domicilio o en un centro hasta un máximo de treinta y seis horas»","Art. 7.1.c LO 5/2000: «c) Internamiento en régimen abierto. Las personas sometidas a esta medida llevarán a cabo todas las actividades del proyecto educativo en los servicios normalizados del entorno»","Art. 10.1 LO 5/2000: «a) si al tiempo de cometer los hechos el menor tuviere catorce o quince años de edad, la medida podrá alcanzar tres años de duración.»","Art. 10.2 LO 5/2000: «b) Si al tiempo de cometer los hechos el menor tuviere dieciséis o diecisiete años de edad, una medida de internamiento en régimen cerrado de uno a ocho años de duración»","Art. 17.1 LO 5/2000: «También deberán notificar inmediatamente el hecho de la detención y el lugar de la custodia a los representantes legales del menor y al Ministerio Fiscal.»","Art. 17.2 LO 5/2000: «2. Toda declaración del detenido, se llevará a cabo en presencia de su letrado y de aquéllos que ejerzan la patria potestad, tutela o guarda del menor»","Art. 17.3 LO 5/2000: «3. Mientras dure la detención, los menores deberán hallarse custodiados en dependencias adecuadas y separadas de las que se utilicen para los mayores de edad»","Art. 17.4 LO 5/2000: «dentro del plazo máximo de veinticuatro horas, el menor detenido deberá ser puesto en libertad o a disposición del Ministerio Fiscal.»","Art. 17.5 LO 5/2000: «éste habrá de resolver, dentro de las cuarenta y ocho horas a partir de la detención»","Art. 17.6 LO 5/2000: «Cuando el procedimiento de hábeas corpus sea instado por el propio menor, la fuerza pública responsable de la detención lo notificará inmediatamente al Ministerio Fiscal»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641', null, null, null, null
  from public.topics t where t.slug = 'plcat-t18-menors'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t19-violencia-masclista', 'Tema 19. Violència masclista i domèstica: Llei 5/2008, LO 1/2004 i ordre de protecció') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t19-violencia-masclista' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Concepte de violència masclista i formes (Llei 5/2008)"},{"n":"2","title":"Àmbits de la violència masclista"},{"n":"3","title":"LO 1/2004: objecte i drets de les víctimes"},{"n":"4","title":"Unitats de valoració policial i protecció"},{"n":"5","title":"Ordre de protecció (art. 544 ter LECrim)"},{"n":"6","title":"Maltractament en l''àmbit familiar (art. 153 CP)"}]'::jsonb, '["Art. 1.1 LO 1/2004: «se ejerce sobre éstas por parte de quienes sean o hayan sido sus cónyuges o de quienes estén o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia.»","Art. 1.3 LO 1/2004: «3. La violencia de género a que se refiere la presente Ley comprende todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad.»","Art. 1.4 LO 1/2004: «4. La violencia de género a que se refiere esta Ley también comprende la violencia que con el objetivo de causar perjuicio o daño a las mujeres se ejerza sobre sus familiares o allegados menores de edad por parte de las personas indicadas en el apartado primero.»","Art. 31.2 LO 1/2004: «para que las Policías Locales, en el marco de su colaboración con las Fuerzas y Cuerpos de Seguridad del Estado, cooperen en asegurar el cumplimiento de las medidas acordadas por los órganos judiciales»","Art. 3 Llei 5/2008: «tiene como resultado un daño o sufrimiento físico, sexual o psicológico, tanto si se produce en el ámbito público como en el privado.»","Art. 4 Llei 5/2008: «b) Violencia psicológica: comprende toda conducta u omisión que produce en una mujer una desvaloración o un sufrimiento»","Art. 5 Llei 5/2008: «Incluye los matrimonios forzados. No incluye la violencia ejercida en el ámbito de la pareja.»","Art. 11 Llei 5/2008: «deben intervenir obligatoriamente cuando tengan conocimiento de una situación de riesgo o de una evidencia fundamentada de violencia machista»","Art. 31 Llei 5/2008: «1. La Policía de la Generalidad –Mossos d’Esquadra– debe vigilar y controlar el cumplimiento exacto de las medidas acordadas por los órganos judiciales.»","Art. 544 ter LECrim: «1. El Juez de Instrucción dictará orden de protección para las víctimas de violencia doméstica»","Art. 544 ter.3 LECrim: «3. La orden de protección podrá solicitarse directamente ante la autoridad judicial o el Ministerio Fiscal, o bien ante las Fuerzas y Cuerpos de Seguridad, las oficinas de atención a la víctima o los servicios sociales o instituciones asistenciales dependientes de las Administraciones públicas.»","Art. 544 ter.4 LECrim: «Durante la audiencia, el Juez de guardia adoptará las medidas oportunas para evitar la confrontación entre el presunto agresor y la víctima, sus hijos y los restantes miembros de la familia.»","Art. 544 ter.5 LECrim: «5. La orden de protección confiere a la víctima de los hechos mencionados en el apartado 1 un estatuto integral de protección que comprenderá las medidas cautelares de orden civil y penal contempladas en este artículo y aquellas otras medidas de asistencia y protección social establecidas en el ordenamiento jurídico.»","Art. 153 Codi penal: «será castigado con la pena de prisión de seis meses a un año o de trabajos en beneficios de la comunidad de treinta y uno a ochenta días y, en todo caso, privación del derecho a la tenencia y porte de armas de un año y un día a tres años»","Art. 31.1 LO 1/2004: «1. El Gobierno establecerá, en las Fuerzas y Cuerpos de Seguridad del Estado, unidades especializadas en la prevención de la violencia de género y en el control de la ejecución de las medidas judiciales adoptadas.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760', null, null, null, 'Otras normas citadas: Llei 5/2008 (https://www.boe.es/buscar/act.php?id=BOE-A-2008-9294), LECrim (https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036), Codi penal (https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444)'
  from public.topics t where t.slug = 'plcat-t19-violencia-masclista'
