insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 11/2009, de 6 de julio, de regulación administrativa de los espectáculos públicos y las actividades recreativas (Cataluña) (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t21-espectacles-publics', 'Tema 21. La Llei 11/2009 d''espectacles públics i activitats recreatives: competències, control i règim sancionador') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t21-espectacles-publics' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Objecte i àmbit de la Llei 11/2009"},{"n":"2","title":"Competències de la Generalitat i dels ajuntaments"},{"n":"3","title":"Llicències i comunicacions prèvies"},{"n":"4","title":"Control i inspecció: funcions dels agents"},{"n":"5","title":"Mesures provisionals"},{"n":"6","title":"Infraccions, sancions i prescripció"}]'::jsonb, '["Art. 1 Llei 11/2009: «El objeto de la presente ley es establecer el régimen jurídico de los espectáculos públicos, las actividades recreativas, así como los establecimientos y los espacios abiertos al público donde se llevan a cabo dichas actividades, y regular su intervención administrativa.»","Art. 3 Llei 11/2009: «b) Actividades recreativas: actividades musicales que congregan a un público con el objetivo principal de hacerle participar en la actividad o de ofrecerle el consumo de productos o servicios con finalidades de ocio, entretenimiento o diversión.»","Art. 9 Llei 11/2009: «especialmente la relativa a la prohibición de venta y suministro de bebidas alcohólicas»","Art. 10 Llei 11/2009: «El ejercicio del derecho de admisión no puede conllevar, en ningún caso, discriminación por razón de nacimiento, raza, sexo, religión, opinión, discapacidad, orientación sexual, identidad de género o cualquier otra condición»","Art. 13 Llei 11/2009: «a) Aprobar ordenanzas, en el marco establecido por esta ley.»","Art. 24 Llei 11/2009: «Este personal debe asistir a cursos de formación impartidos por un centro debidamente habilitado y superar las pruebas de selección que convoque la dirección general competente en materia de espectáculos públicos y actividades recreativas.»","Art. 44 Llei 11/2009: «Pueden realizar inspecciones los miembros de cuerpos y fuerzas de seguridad u otros servicios de inspección, los cuales, en el ejercicio de sus funciones, tienen el carácter de agentes de la autoridad»","Art. 44.3 Llei 11/2009: «3. Como resultado de la inspección, los agentes actuantes deben extender un acta, en la cual los interesados pueden hacer constar su disconformidad y observaciones.»","Art. 47 Llei 11/2009: «c) Exceder el aforo permitido, si supone un riesgo para la seguridad de las personas.»","Art. 48 Llei 11/2009: «f) Exceder el aforo permitido, si no supone un riesgo para la seguridad de las personas.»","Art. 50 Llei 11/2009: «a) Una multa de 10.001 a 100.000 euros y, en caso de reincidencia en la comisión de faltas muy graves, de hasta 200.000 euros.»","Art. 52 Llei 11/2009: «b) Si los infractores son espectadores o usuarios, una multa de 50 a 150 euros y, en caso de reincidencia en la comisión de faltas leves, de hasta 300 euros.»","Art. 57 Llei 11/2009: «1. Las faltas muy graves prescriben al cabo de tres años; las faltas graves, al cabo de dos años, y las faltas leves, al cabo de seis meses.»","Art. 57.2 Llei 11/2009: «En el caso de infracciones derivadas de una actividad continuada, la fecha inicial del cómputo es la de la finalización de la actividad o el último acto con el que la infracción se consuma.»","Art. 62 Llei 11/2009: «En tal caso, el órgano que acuerda la medida provisional debe comunicarlo a la autoridad judicial dentro de las cuarenta y ocho horas siguientes.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856', null, null, null, null
  from public.topics t where t.slug = 'plcat-t21-espectacles-publics'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
