insert into public.sources (title, url, kind, publisher, published_on) values ('Acord GOV/25/2015, de 24 de febrer, pel qual s''aprova el Codi d''ètica de la Policia de Catalunya (DOGC núm. 6821, 26/02/2015)', 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656', 'diario_autonomico'::public.source_kind, 'Generalitat de Catalunya · Portal Jurídic de Catalunya', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('plcat-t22-etica-policial', 'Tema 22. Ètica i deontologia policial: Codi d''ètica de la Policia de Catalunya i Comitè d''Ètica') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local') and t.slug = 'plcat-t22-etica-policial' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Comitè d''Ètica de la Policia de Catalunya: naturalesa i funcions (Decret 222/2013)"},{"n":"2","title":"Composició, nomenament i funcionament"},{"n":"3","title":"Codi d''ètica de la Policia de Catalunya: finalitat"},{"n":"4","title":"Valors: dignitat, servei, integritat i professionalitat"},{"n":"5","title":"Principis d''actuació: legalitat, imparcialitat, proporcionalitat"},{"n":"6","title":"Ús de la força i tracte a les persones detingudes"}]'::jsonb, '["Art. 1 Decret 222/2013: «1.1 El Comitè d''Ètica de la Policia de Catalunya és l’òrgan de caràcter consultiu i interdisciplinari en matèria d’ètica policial de les institucions pròpies de Catalunya»","Art. 3 Decret 222/2013: «3.1 El Comitè d''Ètica de la Policia de Catalunya està integrat per deu membres»","Art. 3.2 Decret 222/2013: «c) Dos entre els membres dels cossos de policia local de Catalunya, a proposta de les entitats municipalistes més representatives, amb una antiguitat mínima de deu anys com a policia local»","Art. 3.3 Decret 222/2013: «3.3 Els membres del Comitè són nomenats per un únic període de quatre anys.»","Art. 6 Decret 222/2013: «El Comitè s''ha de reunir almenys un cop cada quadrimestre.»","Art. 2.1.b Decret 222/2013: «b) Informar i, si s’escau, donar resposta a les qüestions que li adrecin la persona titular del departament amb competències en matèria de seguretat pública i els alcaldes com a responsables de la seguretat en els municipis respectius»","Codi d''ètica, cap. I Codi d''ètica de la Policia de Catalunya: «Es concreten en tres: a. Garantir els drets i les llibertats de totes les persones, b. Actuar amb integritat, proporcionalitat, congruència i oportunitat, i c. Actuar amb absoluta neutralitat política i imparciali»","Codi d''ètica, Proximitat Codi d''ètica de la Policia de Catalunya: «Per proximitat s’entén que l’agent de policia ha de ser accessible al ciutadà i ha d’exercir la funció que li correspon amb amabilitat i empatia per tal de fer-se proper a tota persona.»","Codi d''ètica, Temprança Codi d''ètica de la Policia de Catalunya: «La temprança és aquella qualitat humana que predisposa a l''autodomini mental, al control emocional i a l’autoconsciència»","Codi d''ètica, Professionalitat Codi d''ètica de la Policia de Catalunya: «La professionalitat implica el domini de coneixements (saber) i d''habilitats (saber fer) i unes actituds adequades (saber estar).»","Codi d''ètica, Integritat Codi d''ètica de la Policia de Catalunya: «també s’hi ha d’incloure l’obligació de denunciar i de perseguir tot acte de corrupció o qualsevol proposta que signifiqui un afavoriment indegut, injustificat o il·legal.»","Codi d''ètica, punt 7 Codi d''ètica de la Policia de Catalunya: «els agents de la Policia de Catalunya no poden acceptar ni oferir tracte de favor, contraprestacions ni regals per haver desenvolupat o per desenvolupar el servei públic que els correspon»","Codi d''ètica, punt 8 Codi d''ètica de la Policia de Catalunya: «els agents de policia s’han d’abstenir d’expressar públicament les seves legítimes opcions polítiques o religioses»","Codi d''ètica, punt 17 Codi d''ètica de la Policia de Catalunya: «Els agents de policia han d’actuar d’acord amb el principi de jerarquia. Però, en cap cas, l’obediència deguda pot emparar ordres o actes contraris a l’ordenament legal.»","Codi d''ètica, punt 13 Codi d''ètica de la Policia de Catalunya: «Les relacions entre els membres de la Policia de Catalunya han d’estar regides per l’esperit de cooperació, col·laboració, coordinació, complementarietat i auxili mutu.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656'), 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656', null, null, null, 'Otras normas citadas: Decret 222/2013 (https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=643826)'
  from public.topics t where t.slug = 'plcat-t22-etica-policial'
